// Logic tests for the pure Claude files. Run with ./run.sh (no Xcode test target needed).
import AppKit
import CryptoKit
import Foundation

nonisolated(unsafe) var failures = 0
// Message passes the gates mint go to a temp folder, never Aris's own (~/.config/aris).
ArisMessagePass.folderOverride = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent("aris-test-passes-\(UUID().uuidString)")
// The user's own login shell is never started by the tests (ArisLoginPath): only the usual folders are searched.
ArisLoginPath.override = []
// The automatic check's default list and calendar are taken as the user's own (the app's word in a real turn), and the calendar
// `use-calendar` saved is never read from his folder (fix-7-tests sets other answers where it tests them).
ArisAutoMode.places = { ArisAutoPlaces(list: true, calendar: true) }
ArisAutoMode.savedCalendar = { nil }
// The lists of System Settings are named as on macOS 26, whatever Mac the tests run on (macOS 27 renamed Accessibility:
// ArisFix.Pane.title). The tests of the names themselves ask for each macOS by number (one-row-tests.swift).
ArisFix.Pane.osMajorForTests = 26
/// A UserDefaults suite for a test, by its path in run.sh's throwaway folder: a suite named by a path is that file, so
/// nothing a test sets ever reaches the user's ~/Library/Preferences (the aris-*-tests plists that kept coming back).
func testSuiteName(_ name: String) -> String {
    let folder = ProcessInfo.processInfo.environment["ARIS_TEST_PREFS"] ?? (NSTemporaryDirectory() + "aris-test-prefs")
    try? FileManager.default.createDirectory(atPath: folder, withIntermediateDirectories: true)
    return folder + "/" + name
}

func check(_ condition: Bool, _ name: String, line: Int = #line) {
    if condition { print("ok   \(name)") } else { failures += 1; print("FAIL \(name) (line \(line))") }
}

func event(_ json: [String: Any]) -> ClaudeHookEvent { ClaudeHookEvent(json: json)! }
func body(_ decision: ClaudeDecision, input: [String: Any] = [:]) -> [String: Any] {
    let data = decision.responseBody(input: input)!
    let root = try! JSONSerialization.jsonObject(with: data) as! [String: Any]
    return (root["hookSpecificOutput"] as! [String: Any])["decision"] as! [String: Any]
}

// --- event parsing / state mapping
check(ClaudeHookEvent(json: ["foo": 1]) == nil, "event: missing basics -> nil")
let geminiTool = ClaudeHookEvent(json: ["hook_event_name": "BeforeTool", "session_id": "g1", "cwd": "/p/app", "tool_name": "run_shell_command"], headers: ["x-agent": "Gemini"])
check(geminiTool?.agent == "gemini" && geminiTool?.name == "PreToolUse", "event: Gemini's BeforeTool is PreToolUse, from gemini")
check(ClaudeHookEvent(json: ["hook_event_name": "AfterAgent", "session_id": "g1"], headers: ["x-agent": "gemini"])?.name == "Stop", "event: Gemini's AfterAgent is Stop")
check(ClaudeHookEvent(json: ["hook_event_name": "Stop", "session_id": "c1"], headers: ["x-agent": "codex"])?.agent == "codex", "event: Codex keeps Claude's names")
check(ClaudeHookEvent(json: ["hook_event_name": "Stop", "session_id": "c1"], headers: ["x-agent": "evil"])?.agent == "claude"
      && ClaudeHookEvent(json: ["hook_event_name": "Stop", "session_id": "c1"])?.agent == "claude", "event: unknown or no agent -> claude")
var codexSession = ClaudeSession(id: "s", cwd: "/p/notch", state: .idle, lastEvent: Date())
codexSession.agent = "codex"
check(codexSession.title == "Codex · notch" && ClaudeSession(id: "s", cwd: "/p/notch", state: .idle, lastEvent: Date()).title == "notch", "session: other agents are named in the title")
check(event(["hook_event_name": "UserPromptSubmit", "session_id": "s"]).claudeState == .thinking, "state: prompt -> thinking")
check(event(["hook_event_name": "PreToolUse", "session_id": "s", "tool_name": "Bash"]).claudeState == .building, "state: Bash -> building")
check(event(["hook_event_name": "PreToolUse", "session_id": "s", "tool_name": "Task"]).claudeState == .juggling, "state: Task -> juggling")
check(event(["hook_event_name": "Stop", "session_id": "s"]).claudeState == .happy, "state: Stop -> happy")
check(event(["hook_event_name": "Whatever", "session_id": "s"]).claudeState == nil, "state: unknown -> nil")
check(event(["hook_event_name": "Notification", "session_id": "s", "notification_type": "idle_prompt"]).claudeState == .idle,
      "state: 'waiting for your input' nudge is rest, not an hourglass")
check(event(["hook_event_name": "Notification", "session_id": "s", "notification_type": "permission_prompt"]).claudeState == .notification,
      "state: permission nudge -> needs you")
check(event(["hook_event_name": "Notification", "session_id": "s"]).claudeState == .notification, "state: untyped notification -> needs you")

