// --- approval fixtures
func approval(_ kind: ClaudeApproval.Kind) -> ClaudeApproval { ClaudeApproval(id: UUID(), sessionId: "s", cwd: "/p", toolName: "T", summary: "", kind: kind) }
let single = ClaudeQuestion(header: "", question: "Q", options: [ClaudeOption(label: "A", detail: ""), ClaudeOption(label: "B", detail: "")], multiSelect: false)

// --- responses
check(body(.allow)["behavior"] as? String == "allow", "response: allow")
check(body(.deny)["behavior"] as? String == "deny", "response: deny")
check(ClaudeDecision.passthrough.responseBody(input: [:]) == nil, "response: passthrough -> nil")
let answered = body(.answer(["Q?": "A"]), input: ["questions": []])
check(((answered["updatedInput"] as? [String: Any])?["answers"] as? [String: String]) == ["Q?": "A"], "response: answers merged into updatedInput")
check((answered["updatedInput"] as? [String: Any])?["questions"] != nil, "response: updatedInput keeps original fields")
let always = body(.allowAlways(rules: suggest.permissionSuggestions!))
check((always["updatedPermissions"] as? [[String: Any]])?.first?["type"] as? String == "addRules", "response: always allow echoes suggestions")
check(approval(.tool).canAlwaysAllow == false, "always: no rules -> unavailable")

// --- HTTP parser
func raw(_ s: String) -> Data { Data(s.utf8) }
check(HTTPRequestParser.parse(raw("POST /hook HTTP/1.1\r\nContent-Length: 2\r\n\r\n{}")) == .complete(HTTPRequest(method: "POST", path: "/hook", body: raw("{}"), headers: ["content-length": "2"])), "http: complete")
check(HTTPRequestParser.parse(raw("POST /hook HTTP/1.1\r\nContent-Length: 5\r\n\r\n{}")) == .incomplete, "http: body incomplete")
check(HTTPRequestParser.parse(raw("POST /hook HTTP/1.1\r\n")) == .incomplete, "http: headers incomplete")
check(HTTPRequestParser.parse(raw("GARBAGE\r\n\r\n")) == .invalid, "http: garbage invalid")
check(HTTPRequestParser.parse(Data(count: HTTPRequestParser.maxBytes + 1)) == .invalid, "http: oversize invalid")

// --- request provenance (CSRF / DNS rebinding)
func req(_ headers: String) -> HTTPRequest {
    guard case .complete(let r) = HTTPRequestParser.parse(raw("POST /hook HTTP/1.1\r\n\(headers)Content-Length: 2\r\n\r\n{}")) else { fatalError() }
    return r
}
check(req("Host: 127.0.0.1:23350\r\nContent-Type: application/json\r\n").isLocalClient, "origin: local host accepted")
check(req("Host: localhost:23350\r\n").isLocalClient, "origin: localhost accepted")
check(!req("Host: 127.0.0.1:23350\r\nOrigin: https://evil.example\r\n").isLocalClient, "origin: browser Origin rejected")
check(!req("Host: evil.example:23350\r\n").isLocalClient, "origin: rebinding Host rejected")
check(!req("Content-Type: application/json\r\n").isLocalClient, "origin: missing Host rejected")
check(req("Content-Type: application/json; charset=utf-8\r\n").isJSON && !req("Content-Type: text/plain\r\n").isJSON, "origin: JSON content-type only")

// --- shared-secret auth (other local processes)
let secret = String(repeating: "a1", count: 32)
check(req("X-Boring-Notch-Token: \(secret)\r\n").hasToken(secret), "token: matching header accepted")
check(!req("").hasToken(secret), "token: missing header rejected")
check(!req("X-Boring-Notch-Token: \(secret.dropLast())b\r\n").hasToken(secret), "token: wrong value rejected")
check(!req("X-Boring-Notch-Token: \(secret.dropLast())\r\n").hasToken(secret), "token: prefix rejected")
check(!req("X-Boring-Notch-Token: \r\n").hasToken(""), "token: empty expected never matches")
check(req("X-Aris-Token: \(secret)\r\n").hasToken(secret), "token: the new header is accepted")
check(!req("X-Aris-Token: \(secret.dropLast())b\r\n").hasToken(secret), "token: a wrong value in the new header is rejected")

let tokenFile = FileManager.default.temporaryDirectory.appendingPathComponent("notch-token-\(UUID().uuidString)")
try! "\(secret)\n".write(to: tokenFile, atomically: true, encoding: .utf8)
check(ClaudeHookToken.load(from: tokenFile) == secret, "token file: trimmed contents")
try! "short".write(to: tokenFile, atomically: true, encoding: .utf8)
check(ClaudeHookToken.load(from: tokenFile) == nil, "token file: too short -> nil")
try? FileManager.default.removeItem(at: tokenFile)
check(ClaudeHookToken.load(from: tokenFile) == nil, "token file: missing -> nil")

// --- store
MainActor.assumeIsolated {
    let store = ClaudeStore()
    @MainActor func send(_ name: String, tool: String? = nil, extra: [String: Any] = [:]) {
        var json: [String: Any] = ["hook_event_name": name, "session_id": "s1", "cwd": "/w/proj"]
        if let tool { json["tool_name"] = tool }
        store.apply(ClaudeHookEvent(json: json.merging(extra) { _, new in new })!)
    }
    send("UserPromptSubmit")
    send("PreToolUse", tool: "Read"); send("PostToolUse", tool: "Read"); send("PreToolUse", tool: "Edit")
    let steps = store.sessions["s1"]!.steps
    check(steps.map(\.tool) == ["Read", "Edit"] && steps.map(\.done) == [true, false], "store: steps start/finish")
    check(store.sessions["s1"]!.title == "proj", "store: title from cwd")
    send("Stop", extra: ["last_assistant_message": "All done"])
    check(store.sessions["s1"]!.steps.allSatisfy(\.done) && store.sessions["s1"]!.lastMessage == "All done", "store: Stop finishes steps, keeps message")
    check(store.currentPeek?.message == "All done", "store: done peek carries message")
    send("UserPromptSubmit")
    check(store.sessions["s1"]!.steps.isEmpty && store.sessions["s1"]!.lastMessage == nil, "store: new prompt resets")
    store.focus("s1"); send("SessionEnd")
    check(store.sessions.isEmpty && store.focusedSessionId == nil, "store: SessionEnd removes + clears focus")

    var got: ClaudeDecision?
    let a = approval(.tool)
    store.requestApproval(a) { got = $0 }
    check(ClaudeStore.hasPendingApproval && store.displayState == .notification, "store: pending approval flags")
    store.decide(a.id, .allow)
    if case .allow? = got { check(true, "store: decision resolves once") } else { check(false, "store: decision resolves once") }
    check(!ClaudeStore.hasPendingApproval, "store: flag cleared after decision")

    // Answered in the terminal: Claude Code keeps the hook request open, so the card must clear on PostToolUse.
    let qInput: [String: Any] = ["questions": [["question": "Pick a color", "options": [["label": "Red"]]]]]
    func pending(_ session: String, _ tool: String, _ input: [String: Any]) -> ClaudeApproval {
        ClaudeApproval(id: UUID(), sessionId: session, cwd: "/p", toolName: tool, summary: "", kind: .tool, toolInput: input as NSDictionary)
    }
    @MainActor func finish(_ name: String, _ session: String, _ tool: String, _ input: [String: Any]) {
        store.apply(ClaudeHookEvent(json: ["hook_event_name": name, "session_id": session, "tool_name": tool, "tool_input": input])!)
    }
    let question = pending("s2", "AskUserQuestion", qInput)
    let otherBash = pending("s2", "Bash", ["command": "rm -rf build"])
    let otherSession = pending("s3", "AskUserQuestion", qInput)
    var resolved = 0
    [question, otherBash, otherSession].forEach { store.requestApproval($0) { _ in resolved += 1 } }
    finish("PostToolUse", "s2", "AskUserQuestion", qInput.merging(["answers": ["Pick a color": "Red"]]) { _, new in new })
    check(store.approvals.map(\.id) == [otherBash.id, otherSession.id], "terminal answer: matching card cleared, others kept")
    finish("PostToolUse", "s2", "Bash", ["command": "ls"])
    check(store.approvals.map(\.id) == [otherBash.id, otherSession.id], "terminal answer: same tool, different input kept")
    finish("PostToolUseFailure", "s2", "Bash", ["command": "rm -rf build"])
    check(store.approvals.map(\.id) == [otherSession.id], "terminal answer: failure clears too")
    store.apply(ClaudeHookEvent(json: ["hook_event_name": "Stop", "session_id": "s3"])!)
    check(store.approvals.isEmpty, "terminal answer: Stop clears the session's leftovers")
    check(resolved == 0, "terminal answer: cleared cards never send a decision")

    // Approvals are answered in the open Claude tab only; the closed-notch banner is just done/error.
    store.requestApproval(approval(.question([single]))) { _ in }
    if case .done? = store.currentPeek?.kind { check(true, "peek: pending approval doesn't take over the banner") }
    else { check(false, "peek: pending approval doesn't take over the banner") }
}

// --- open notch grows downward to fit the Claude tab
check(GrowDownFrame.height(natural: 120, min: 190, max: 400) == 190, "grow: short content keeps the normal height")
check(GrowDownFrame.height(natural: 260, min: 190, max: 400) == 260, "grow: tall content extends the notch")
check(GrowDownFrame.height(natural: 900, min: 190, max: 400) == 400, "grow: capped at the window height")

// --- terminal jump: hook headers -> where the session's terminal is (strictly validated)
let warpURL = "warp://session/724db74117fa4b86b5fc3e08ebb80bd2"
check(TerminalRef(headers: ["x-warp-focus": warpURL, "x-bundle-id": "dev.warp.Warp-Stable"]) == .warp(URL(string: warpURL)!), "terminal: warp focus url wins")
check(TerminalRef(headers: ["x-warp-focus": "warp://action/new_tab?path=/", "x-bundle-id": "dev.warp.Warp-Stable"]) == .app("dev.warp.Warp-Stable"), "terminal: other warp urls rejected")
check(TerminalRef(headers: ["x-warp-focus": "https://evil.example/" + String(repeating: "a", count: 32)]) == nil, "terminal: non-warp url rejected")
check(TerminalRef(headers: ["x-iterm-session": "w0t1p0:6F3C9B2E-1A2B-4C3D-8E9F-0123456789AB"]) == .iterm("6F3C9B2E-1A2B-4C3D-8E9F-0123456789AB"), "terminal: iterm session id")
check(TerminalRef(headers: ["x-iterm-session": "w0t1p0:\" & do shell script"]) == nil, "terminal: malformed iterm id rejected")
check(TerminalRef(headers: ["x-bundle-id": "com.microsoft.VSCode"]) == .app("com.microsoft.VSCode"), "terminal: host app by bundle id")
check(TerminalRef(headers: ["x-bundle-id": "not a bundle id"]) == nil, "terminal: bad bundle id rejected")
check(TerminalRef(headers: ["x-term-program": "Apple_Terminal"]) == .app("com.apple.Terminal"), "terminal: TERM_PROGRAM fallback")
check(TerminalRef(headers: ["x-warp-focus": "", "x-bundle-id": "", "x-term-program": ""]) == nil, "terminal: unset variables -> nil")
let jumpEvent = ClaudeHookEvent(json: ["hook_event_name": "PreToolUse", "session_id": "j", "tool_name": "Bash"], headers: ["x-warp-focus": warpURL])!
check(jumpEvent.terminal == .warp(URL(string: warpURL)!), "terminal: event carries it")
MainActor.assumeIsolated {
    let store = ClaudeStore()
    store.apply(jumpEvent)
    store.apply(event(["hook_event_name": "PostToolUse", "session_id": "j", "tool_name": "Bash"]))
    check(store.sessions["j"]?.terminal == .warp(URL(string: warpURL)!), "terminal: session keeps the last known terminal")
    var handedOff: String?
    store.onHandOff = { approval in handedOff = approval.sessionId }
    let card = ClaudeApproval(id: UUID(), sessionId: "j", cwd: "/p", toolName: "Bash", summary: "", kind: .tool)
    store.requestApproval(card) { _ in }
    store.decide(card.id, .passthrough)
    check(handedOff == "j", "terminal: handing a card to the terminal jumps there")
}

// --- usage meter: statusline JSON -> limits and context
let statusJSON: [String: Any] = ["session_id": "u", "context_window": ["used_percentage": 42.5],
    "rate_limits": ["five_hour": ["used_percentage": 63.2, "resets_at": 1_800_000_000],
                    "seven_day": ["used_percentage": 21, "resets_at": 1_800_400_000]]]
let report = ClaudeStatusReport(json: statusJSON)!
check(report.sessionId == "u" && report.contextPercent == 42.5, "usage: session and context %")
check(report.fiveHour == UsageWindow(percent: 63.2, resetsAt: Date(timeIntervalSince1970: 1_800_000_000)), "usage: 5h window")
check(report.sevenDay?.percent == 21, "usage: 7d window (integer percent)")
let early = ClaudeStatusReport(json: ["session_id": "u", "context_window": ["used_percentage": 3]])!
check(early.fiveHour == nil && early.contextPercent == 3, "usage: before the first response, no limits yet")
check(ClaudeStatusReport(json: ["rate_limits": ["five_hour": ["used_percentage": "lots", "resets_at": 1]]]) == nil, "usage: junk -> nil")
check(ClaudeStatusReport(json: ["session_id": "u", "context_window": ["used_percentage": 250]])?.contextPercent == 100, "usage: percent clamped")
let usage = ClaudeUsage(updatedAt: Date(timeIntervalSince1970: 0)).merging(report, now: Date(timeIntervalSince1970: 10))
check(usage.merging(early, now: Date(timeIntervalSince1970: 20)).fiveHour?.percent == 63.2, "usage: a report without limits keeps the last known ones")
check(UsageWindow(percent: 90, resetsAt: Date(timeIntervalSince1970: 100)).percent(at: Date(timeIntervalSince1970: 101)) == 0, "usage: a window past its reset reads 0%")
check(ClaudeUsage.crossed(from: 79, to: 81) == 80 && ClaudeUsage.crossed(from: 81, to: 96) == 95, "usage: crossing 80 / 95 warns")
check(ClaudeUsage.crossed(from: 81, to: 85) == nil && ClaudeUsage.crossed(from: nil, to: 50) == nil, "usage: no warning without a crossing")
MainActor.assumeIsolated {
    let store = ClaudeStore()
    store.apply(event(["hook_event_name": "UserPromptSubmit", "session_id": "u"]))
    store.applyStatus(ClaudeStatusReport(json: ["session_id": "u", "context_window": ["used_percentage": 10],
        "rate_limits": ["five_hour": ["used_percentage": 70, "resets_at": 1_800_000_000]]])!)
    check(store.usage?.fiveHour?.percent == 70 && store.sessions["u"]?.contextPercent == 10, "store: usage and session context applied")
    check(store.currentPeek == nil, "store: below the threshold, no banner")
    store.applyStatus(report)
    check(store.sessions["u"]?.contextPercent == 42.5, "store: context updates")
    store.applyStatus(ClaudeStatusReport(json: ["rate_limits": ["five_hour": ["used_percentage": 81, "resets_at": 1_800_000_000]]])!)
    if case .limit? = store.currentPeek?.kind { check(store.currentPeek?.title == "80% used", "store: crossing 80% shows a limit banner") }
    else { check(false, "store: crossing 80% shows a limit banner") }
}

// --- question flow: answers live in the store, one question at a time
func question(_ text: String, _ labels: [String], multi: Bool = false) -> ClaudeQuestion {
    ClaudeQuestion(header: text, question: text, options: labels.map { ClaudeOption(label: $0, detail: "") }, multiSelect: multi)
}
let four = [question("Q1", ["a", "b"]), question("Q2", ["c", "d"]), question("Q3", ["e", "f", "g"], multi: true), question("Q4", ["h", "i"])]
let fresh = QuestionFlow(questions: four)
check(fresh.current == 0 && !fresh.isComplete, "flow: starts on the first question, incomplete")
let afterPick = fresh.picking("a")
check(afterPick.current == 1, "flow: single-select pick moves to the next question")
check(fresh.picked.isEmpty, "flow: picking returns a new value, original untouched")
let multiPicked = afterPick.picking("c").picking("e").picking("g")
check(multiPicked.current == 2, "flow: multi-select pick stays on the question")
check(multiPicked.picking("e").answer(for: four[2]) == "g", "flow: multi-select tap again unpicks")
let allFour = multiPicked.moving(to: 3).picking(index: 1)
check(allFour.isComplete, "flow: all four questions answerable (no hidden 4th question)")
check(allFour.answers == ["Q1": "a", "Q2": "c", "Q3": "e, g", "Q4": "i"], "flow: answers keep option order")
check(fresh.picking(index: 9).picked.isEmpty, "flow: out-of-range number ignored")
check(fresh.moving(to: 99).current == 3 && fresh.moving(to: -5).current == 0, "flow: moving is clamped")
let typedFlow = fresh.typing("my own")
check(typedFlow.answer(for: four[0]) == "my own" && typedFlow.current == 0, "flow: typed answer counts, stays put while typing")
check(typedFlow.picking("b").answer(for: four[0]) == "b", "flow: single-select pick replaces typed text")
check(fresh.typing("   ").answer(for: four[0]) == nil, "flow: blank typed text is no answer")
check(QuestionFlow(questions: [single]).answersOnTap && !fresh.answersOnTap, "flow: only one single-select question answers on tap")
check(QuestionFlow.Key(keyCode: 18) == .option(0) && QuestionFlow.Key(keyCode: 25) == .option(8), "keys: 1 and 9 by physical key code")
check(QuestionFlow.Key(keyCode: 36) == .submit && QuestionFlow.Key(keyCode: 53) == .terminal, "keys: return submits, esc goes to terminal")
check(QuestionFlow.Key(keyCode: 124) == .next && QuestionFlow.Key(keyCode: 123) == .previous && QuestionFlow.Key(keyCode: 0) == nil, "keys: arrows move, others ignored")

MainActor.assumeIsolated {
    let store = ClaudeStore()
    var decided: ClaudeDecision?
    let card = approval(.question(four))
    store.requestApproval(card) { decided = $0 }
    check(store.flows[card.id]?.questions.count == 4, "store: question card gets a flow")
    store.pick("a", in: card.id)
    store.submit(card.id)
    check(decided == nil && store.approvals.count == 1, "store: incomplete submit does nothing")
    _ = store.handleQuestionKey(18)   // Q2 -> c
    store.pick("e", in: card.id)
    _ = store.handleQuestionKey(124)  // -> Q4
    _ = store.handleQuestionKey(19)   // Q4 -> i
    check(store.handleQuestionKey(36), "store: return handled on a question card")
    if case .answer(let answers)? = decided { check(answers == ["Q1": "a", "Q2": "c", "Q3": "e", "Q4": "i"], "store: keyboard answers all four") }
    else { check(false, "store: keyboard answers all four") }
    check(store.flows.isEmpty && store.approvals.isEmpty, "store: answered card and its flow are gone")

    var tapped: ClaudeDecision?
    let one = approval(.question([single]))
    store.requestApproval(one) { tapped = $0 }
    store.pick("B", in: one.id)
    if case .answer(let answers)? = tapped { check(answers == ["Q": "B"], "store: single question answers on tap") }
    else { check(false, "store: single question answers on tap") }

    let tool = approval(.tool)
    store.requestApproval(tool) { _ in }
    check(!store.handleQuestionKey(18), "store: number keys ignored on a tool card")
    store.cancelApproval(tool.id)
    let gone = approval(.question(four))
    store.requestApproval(gone) { _ in }
    store.cancelApproval(gone.id)
    check(store.flows.isEmpty, "store: cancelled card drops its flow")
}

// --- store: an open but resting session still has a presence
MainActor.assumeIsolated {
    let store = ClaudeStore()
    check(!store.hasSessions, "store: empty -> no presence")
    store.apply(event(["hook_event_name": "SessionStart", "session_id": "rest", "cwd": "/p"]))
    check(store.hasSessions && !store.isLive, "store: idle session -> present but not live")
    store.apply(event(["hook_event_name": "SessionEnd", "session_id": "rest", "cwd": "/p"]))
    check(!store.hasSessions, "store: ended session -> gone")
}

// --- right ear: the icon in the middle
func earSession(_ id: String, _ state: ClaudeState, tools: [String] = [], at seconds: Double = 0) -> ClaudeSession {
    ClaudeSession(id: id, cwd: "/p", state: state, lastEvent: Date(timeIntervalSince1970: seconds),
                  steps: tools.map { ClaudeStep(tool: $0, done: false) })
}
check(EarCenter.pick(state: .sleeping, sessions: []) == .resting, "ear: no sessions -> moon")
check(EarCenter.pick(state: .idle, sessions: [earSession("a", .idle)]) == .resting, "ear: idle -> moon")
check(EarCenter.pick(state: .happy, sessions: [earSession("a", .happy)]) == .done, "ear: happy -> check")
check(EarCenter.pick(state: .error, sessions: [earSession("a", .error)]) == .error, "ear: error -> !")
check(EarCenter.pick(state: .notification, sessions: [earSession("a", .building, tools: ["Bash"])]) == .waiting,
      "ear: pending approval wins over work -> hourglass")
check(EarCenter.pick(state: .building, sessions: [earSession("a", .building, tools: ["Bash"])]) == .tool(.terminal), "ear: Bash -> terminal")
check(EarCenter.pick(state: .typing, sessions: [earSession("a", .typing, tools: ["Bash", "Edit"])]) == .tool(.edit), "ear: latest tool wins (Edit -> pencil)")
check(EarCenter.pick(state: .typing, sessions: [earSession("a", .typing, tools: ["Grep"])]) == .tool(.search), "ear: Grep -> magnifier")
check(EarCenter.pick(state: .juggling, sessions: [earSession("a", .juggling, tools: ["Task"])]) == .tool(.agents), "ear: Task -> agents")
check(EarCenter.pick(state: .thinking, sessions: [earSession("a", .thinking)]) == .tool(.thinking), "ear: no tool yet -> thinking")
check(EarCenter.pick(state: .typing, sessions: [earSession("a", .typing, tools: ["mcp__x__y"])]) == .tool(.thinking), "ear: unknown tool -> thinking")
check(EarCenter.pick(state: .building, sessions: [earSession("a", .typing, tools: ["Read"], at: 9),
                                                   earSession("b", .building, tools: ["Bash"], at: 1)]) == .tool(.terminal),
      "ear: tool comes from the session in the shown state")
check(EarCenter.pick(state: .typing, sessions: [earSession("a", .typing, tools: ["Read"], at: 1),
                                                 earSession("b", .typing, tools: ["Write"], at: 5)]) == .tool(.edit),
      "ear: ties go to the most recent session")

// MARK: - Auto-close after the last approval (each display decides for itself)
check(ApprovalAutoClose.shouldClose(isOpen: true, hovering: false, openedForApproval: true, showingClaude: true), "autoclose: opened for the card, not hovered -> close")
check(ApprovalAutoClose.shouldClose(isOpen: true, hovering: false, openedForApproval: true, showingClaude: false), "autoclose: another display already flipped the shared tab -> still close")
check(!ApprovalAutoClose.shouldClose(isOpen: true, hovering: true, openedForApproval: true, showingClaude: true), "autoclose: pointer on this notch -> leave it")
check(!ApprovalAutoClose.shouldClose(isOpen: false, hovering: false, openedForApproval: true, showingClaude: true), "autoclose: already closed -> nothing")
check(!ApprovalAutoClose.shouldClose(isOpen: true, hovering: false, openedForApproval: false, showingClaude: false), "autoclose: user opened it for something else -> leave it")
