// Claude Code ignores hook answers to plan approval, so Y on a plan card hands it to the terminal.
MainActor.assumeIsolated {
    let store = ClaudeStore()
    var decided: ClaudeDecision?
    store.requestApproval(approval(.plan("p"))) { decided = $0 }
    check(store.decideFirstTool(.allow), "store: Y answers a plan card")
    if case .passthrough? = decided { check(true, "store: Y on a plan -> terminal") } else { check(false, "store: Y on a plan -> terminal") }
    var tool: ClaudeDecision?
    store.requestApproval(approval(.tool)) { tool = $0 }
    _ = store.decideFirstTool(.allow)
    if case .allow? = tool { check(true, "store: Y on a tool stays a plain allow") } else { check(false, "store: Y on a tool stays a plain allow") }
}

