// MARK: - Aris: the to-do list
let todoNow = ISO8601DateFormatter().date(from: "2026-10-31T15:00:00Z")!
var todoList = ArisTodoList().adding("우유 사기", now: todoNow, id: "a").adding("  엄마한테 전화 ", now: todoNow, id: "b")
check(todoList.todos.map(\.text) == ["우유 사기", "엄마한테 전화"], "todo: added, trimmed")
check(todoList.adding("우유  사기", now: todoNow, id: "c") == todoList && todoList.adding("  ", now: todoNow) == todoList, "todo: no duplicates or blanks")
if let finished = todoList.finishing("우유 사기 다 했어", now: todoNow) {
    check(finished.done.id == "a" && finished.done.done && finished.list.todos[1].done == false, "todo: '우유 사기 다 했어' ticks off that one")
    todoList = finished.list
} else { check(false, "todo: '우유 사기 다 했어' should match") }
check(ArisTodoList().adding("과제 1", now: todoNow).adding("과제 2", now: todoNow).finishing("과제", now: todoNow) == nil, "todo: words matching two items tick off neither")
check(todoList.shown(now: todoNow).map(\.id) == ["b", "a"], "todo: open first, today's done after")
check(todoList.shown(now: todoNow.addingTimeInterval(2 * 86_400)).map(\.id) == ["b"], "todo: yesterday's done ones leave the list")
check(todoList.pruned(now: todoNow.addingTimeInterval(8 * 86_400)).todos.map(\.id) == ["b"], "todo: done ones are forgotten after a week")
check(todoList.toggling("a", now: todoNow).todos[0].done == false && todoList.removing("b").todos.count == 1, "todo: untick and remove")
check(todoList.hidingDue("x").hidingDue("x").hiddenDue == ["x"], "todo: a Canvas deadline is hidden once")
let dueSoon = ArisDue(id: "9", course: "CSC263H1", title: "PS3", at: todoNow.addingTimeInterval(20 * 3_600), url: nil)
check(ArisDueAlert.pending(for: dueSoon, now: todoNow, shown: []) == .dayBefore, "due alert: within a day -> the blue one")
check(ArisDueAlert.pending(for: dueSoon, now: todoNow, shown: ["9:24h"]) == nil, "due alert: shown once")
check(ArisDueAlert.pending(for: dueSoon, now: todoNow.addingTimeInterval(18 * 3_600), shown: ["9:24h"]) == .hoursBefore, "due alert: within 3 hours -> the red one")
check(ArisDueAlert.pending(for: dueSoon, now: todoNow.addingTimeInterval(21 * 3_600), shown: []) == nil, "due alert: nothing once it's past")
let dueList = [ArisDue(id: "1", course: "CSC263H1", title: "Problem Set 3", at: todoNow, url: nil),
               ArisDue(id: "2", course: "STA247H1", title: "Lab 5", at: todoNow, url: nil)]
check(ArisDueMatch.one("problem set 3", in: dueList)?.id == "1" && ArisDueMatch.one("STA247 Lab 5", in: dueList)?.id == "2"
      && ArisDueMatch.one("과제", in: dueList) == nil, "due match: by title or course + title, one only")
let decodedList = try? JSONDecoder().decode(ArisTodoList.self, from: JSONEncoder().encode(todoList))
check(decodedList == todoList, "todo: saved and read back")

check(ArisIntent.parse("할 일 추가해 우유 사기") == .addTodo("우유 사기"), "aris: 할 일 추가해 X -> add X")
check(ArisIntent.parse("우유 사기 할 일에 추가해줘") == .addTodo("우유 사기"), "aris: X 할 일에 추가해줘 -> add X")
check(ArisIntent.parse("할일 추가: 엄마한테 전화") == .addTodo("엄마한테 전화"), "aris: 할일 추가: X")
