// MARK: - Clipboard history (after Maccy)
func clipItem(_ text: String, _ at: TimeInterval = 0, extra: [ArisClipboard.Content] = []) -> ArisClipboard.Item {
    let contents = [ArisClipboard.Content(type: ArisClipboard.stringType, data: Data(text.utf8))] + extra
    return ArisClipboard.Item(id: UUID(), contents: contents, title: ArisClipboard.title(of: contents), app: "Safari", appBundle: "com.apple.Safari",
                              firstCopied: Date(timeIntervalSince1970: at), lastCopied: Date(timeIntervalSince1970: at))
}
var clips = ArisClipboard.adding(clipItem("hello", 1), to: [])
clips = ArisClipboard.adding(clipItem("https://q.exampleu.edu", 2), to: clips)
check(clips.map(\.title) == ["https://q.exampleu.edu", "hello"], "clipboard: newest first")
let again = ArisClipboard.adding(clipItem("hello", 3), to: clips)
check(again.map(\.title) == ["hello", "https://q.exampleu.edu"] && again[0].copies == 2 && again[0].firstCopied == Date(timeIntervalSince1970: 1),
      "clipboard: copying again moves it up, counts it, keeps the first date")
let rich = ArisClipboard.adding(clipItem("hello", 4, extra: [ArisClipboard.Content(type: "public.rtf", data: Data("{\\rtf1 hello}".utf8))]), to: again)
check(rich.count == 2 && rich[0].contents.count == 2, "clipboard: the same text with formatting covers the plain copy")
var pinnedClips = again
pinnedClips[1].pinned = true
pinnedClips = ArisClipboard.sorted(pinnedClips)
check(pinnedClips.first?.title == "https://q.exampleu.edu" && ArisClipboard.adding(clipItem("new", 9), to: pinnedClips).first?.pinned == true, "clipboard: pinned stay on top")
check((1...250).reduce([ArisClipboard.Item]()) { ArisClipboard.adding(clipItem("item \($1)", Double($1)), to: $0) }.count == ArisClipboard.limit, "clipboard: at most 200 unpinned")
check(!ArisClipboard.keeps(types: ["public.utf8-plain-text", "org.nspasteboard.ConcealedType"], app: "com.apple.Safari"), "clipboard: concealed copies (passwords) are never kept")
check(!ArisClipboard.keeps(types: ["public.utf8-plain-text", "org.nspasteboard.TransientType"], app: nil), "clipboard: transient copies (dictation's paste) are never kept")
check(!ArisClipboard.keeps(types: ["public.utf8-plain-text", ArisClipboard.ownType], app: nil), "clipboard: the notch's own copy isn't recorded again")
check(!ArisClipboard.keeps(types: ["public.utf8-plain-text"], app: "com.1password.1password"), "clipboard: nothing from password apps")
check(ArisClipboard.keeps(types: ["public.utf8-plain-text"], app: "com.apple.Safari"), "clipboard: ordinary text is kept")
check(!ArisClipboard.keepsType("dyn.ah62d4rv4gu8y") && !ArisClipboard.keepsType("com.apple.webarchive") && ArisClipboard.keepsType("public.rtf"), "clipboard: private and huge types dropped")
check(ArisClipboard.looksSecret(clipItem("99999~Qz7Lm2Xp9Rt4Vb8Nc1Kd6Hf3Jg5Ws0Ya7Ue2Io9Pq4Lr8Mt1Zx6Cv3Bn5Aa2Ss"))
      && ArisClipboard.looksSecret(clipItem("sk-ant-api03-Xy7Qp2LmN9vB4kT8")), "clipboard: tokens and keys are never saved to disk")
check(!ArisClipboard.looksSecret(clipItem("https://q.exampleu.edu/courses/12345")) && !ArisClipboard.looksSecret(clipItem("엄마 생일 선물 사기"))
      && !ArisClipboard.looksSecret(clipItem("/Users/me/Desktop/notes.md")) && !ArisClipboard.looksSecret(clipItem("aaaaaaaaaaaaaaaaaaaa1")),
      "clipboard: links, sentences, paths and repeats are saved as usual")
check(ArisClipboard.plain(rich[0].contents).map(\.type) == [ArisClipboard.stringType], "clipboard: paste without formatting keeps just the text")
let searchable = [clipItem("Problem Set 3 due Friday"), clipItem("https://q.exampleu.edu/courses"), clipItem("엄마 생일 선물")]
check(ArisClipboard.search("exampleu", in: searchable).map(\.title) == ["https://q.exampleu.edu/courses"], "clipboard search: exact, any case")
check(ArisClipboard.search("pst3", in: searchable).first?.title == "Problem Set 3 due Friday", "clipboard search: fuzzy when nothing matches exactly")
check(ArisClipboard.search("생일", in: searchable).count == 1 && ArisClipboard.search("", in: searchable).count == 3, "clipboard search: Korean; empty shows all")
check(ArisClipboard.title(of: [ArisClipboard.Content(type: ArisClipboard.fileURLType, data: URL(fileURLWithPath: "/tmp/a.pdf").dataRepresentation)]) == "/tmp/a.pdf",
      "clipboard: files show their paths")

// MARK: - Timer state
let t0 = Date(timeIntervalSince1970: 1_000)
let plainTimer = ArisTimerState.start(seconds: 90, phase: .plain, at: t0)
check(plainTimer.left(at: t0.addingTimeInterval(30)) == 60 && plainTimer.progress(at: t0.addingTimeInterval(45)) == 0.5, "timer state: time left and progress")
let pausedTimer = plainTimer.paused(at: t0.addingTimeInterval(30))
check(pausedTimer.isPaused && pausedTimer.left(at: t0.addingTimeInterval(500)) == 60, "timer state: paused, time stands still")
let resumedTimer = pausedTimer.resumed(at: t0.addingTimeInterval(500))
check(!resumedTimer.isPaused && resumedTimer.left(at: t0.addingTimeInterval(510)) == 50, "timer state: resumed where it stopped")
check(plainTimer.adding(300, at: t0).left(at: t0) == 390 && plainTimer.adding(300, at: t0).total == 390, "timer state: +5 minutes")
check(pausedTimer.adding(60, at: t0).left(at: t0.addingTimeInterval(999)) == 120, "timer state: adding while paused")
check(plainTimer.next(at: t0) == nil, "timer state: a plain timer just ends")
let focus1 = ArisTimerState.start(seconds: ArisTimerState.focusSeconds, phase: .focus, at: t0, round: 1, cycle: true)
let rest1 = focus1.next(at: t0)
check(rest1?.phase == .rest && rest1?.total == ArisTimerState.shortRest && rest1?.round == 1, "pomodoro: focus -> 5 minute break")
check(rest1?.next(at: t0)?.phase == .focus && rest1?.next(at: t0)?.round == 2, "pomodoro: break -> the next focus round")
let focus4 = ArisTimerState.start(seconds: ArisTimerState.focusSeconds, phase: .focus, at: t0, round: 4, cycle: true)
check(focus4.next(at: t0)?.total == ArisTimerState.longRest && focus4.next(at: t0)?.next(at: t0)?.round == 1, "pomodoro: a long break after the 4th, then round 1")
check(ArisTimerState.start(seconds: 1_500, phase: .focus, at: t0).next(at: t0) == nil, "timer state: a single focus session doesn't cycle")
check(ArisTimerState.clock(1_453) == "24:13" && ArisTimerState.clock(59) == "0:59" && ArisTimerState.clock(3_725) == "1:02:05", "timer state: clock text")
let savedTimer = try? JSONDecoder().decode(ArisTimerState.self, from: JSONEncoder().encode(pausedTimer))
check(savedTimer == pausedTimer, "timer state: saved and restored (survives a restart)")

// MARK: - To-do due dates
var todoCalendar = Calendar(identifier: .gregorian)
todoCalendar.timeZone = TimeZone(identifier: "America/New_York")!
let thursday = ISO8601DateFormatter().date(from: "2026-10-29T14:00:00Z")!   // Thu 10:00 in Orlando
func due(_ text: String) -> (String, String?) {
    let parsed = ArisTodoDate.parse(text, now: thursday, calendar: todoCalendar)
    let formatter = DateFormatter()
    formatter.timeZone = todoCalendar.timeZone
    formatter.dateFormat = "EEE M/d HH:mm"
    formatter.locale = Locale(identifier: "en_US_POSIX")
    return (parsed.text, parsed.due.map(formatter.string))
}
check(due("내일까지 보고서") == ("보고서", "Fri 10/30 23:59"), "todo date: 내일까지 -> tomorrow, end of day")
check(due("금요일 3시 발표 준비") == ("발표 준비", "Fri 10/30 15:00"), "todo date: weekday and an afternoon hour")
check(due("오늘 오후 2시 반 회의") == ("회의", "Thu 10/29 14:30"), "todo date: 오후 2시 반")
check(due("다음주 월요일 과제 제출") == ("과제 제출", "Mon 11/2 23:59"), "todo date: 다음주 월요일")
check(due("11월 5일 시험") == ("시험", "Thu 11/5 23:59"), "todo date: month and day")
check(due("3시에 엄마한테 전화") == ("엄마한테 전화", "Thu 10/29 15:00"), "todo date: a time alone is today")
check(due("오전 9시 수업") == ("수업", "Fri 10/30 09:00"), "todo date: a time already past is tomorrow")
check(due("일요일까지 빨래") == ("빨래", "Sun 11/1 23:59"), "todo date: 일요일까지")
check(due("우유 사기") == ("우유 사기", nil) && due("월급 확인") == ("월급 확인", nil) && due("1일 1커밋") == ("1일 1커밋", nil), "todo date: no date, no guess")
let datedList = ArisTodoList().adding("우유 사기", now: thursday, id: "x", calendar: todoCalendar)
    .adding("내일까지 보고서", now: thursday, id: "y", calendar: todoCalendar)
check(datedList.shown(now: thursday).map(\.id) == ["y", "x"] && datedList.todos.first { $0.id == "y" }?.text == "보고서", "todo: dated items first, the date taken out of the text")
check(datedList.editing("x", to: "모레 우유 사기", now: thursday, calendar: todoCalendar).todos.first { $0.id == "x" }?.due != nil, "todo: editing re-reads the date")
check(datedList.dueItems().map(\.title) == ["보고서"] && datedList.dueItems().first?.course == "할 일", "todo: dated items join the deadline alerts")
check(ArisIntent.parse("할 일 뭐 있어") == .listTodos && ArisIntent.parse("오늘 할 일 알려줘") == .listTodos, "aris: what's on my list, locally")

