check(ArisTranscript.pick(whisper: nil, apple: "노래 꺼줘", heardVoice: true) == "노래 꺼줘", "transcript: no Whisper (not ready, slow) -> Apple's")
check(ArisTranscript.pick(whisper: "  ", apple: "노래 꺼줘", heardVoice: true) == "노래 꺼줘", "transcript: blank Whisper -> Apple's")
