check(ArisTranscript.pick(whisper: "*sad music*", apple: "", heardVoice: true, voiceFrames: 200, loudest: 0.9) == "", "BUG-30: an annotation is never words, however loud")
check(ArisTranscript.pick(whisper: "아리스, 오늘 날씨 어때?", apple: "", heardVoice: true) == "", "BUG-30: Whisper alone with no voice evidence -> nothing")
check(ArisTranscript.pick(whisper: "Turn it down a bit.", apple: "", heardVoice: true, voiceFrames: 5, loudest: 0.1246) == "", "BUG-30: loudest 0.12 with no recognizer words is noise")
check(ArisTranscript.pick(whisper: "Turn it down a bit.", apple: "", heardVoice: true, voiceFrames: 40, loudest: 0.1246) == "", "BUG-30: long but quiet noise is still noise")
