// MARK: - Aris router: reading and deciding
func jevReply(_ intent: String, _ intentConfidence: Double, app: String = "none", _ appConfidence: Double = 0.9) -> Data {
    let body: [String: Any] = ["model": "jev-1.14.0", "answers": [
        "intent": ["type": "choice", "choice": intent, "confidence": intentConfidence, "probabilities": [intent: 0.9]],
        "app": ["type": "choice", "choice": app, "confidence": appConfidence, "probabilities": [app: 0.9]],
    ]]
    return try! JSONSerialization.data(withJSONObject: body)
}
let nextAnswers = ArisRouter.parse(jevReply("next_track", 0.92))
check(nextAnswers?.intent == .nextTrack && nextAnswers?.intentConfidence == 0.92, "router: reads the intent and its confidence")
check(ArisRouter.parse(Data("not json".utf8)) == nil, "router: broken reply -> nothing")
check(ArisRouter.parse(Data(#"{"answers":{}}"#.utf8)) == nil, "router: missing answers -> nothing")
check(ArisRouter.parse(jevReply("dance", 0.99)) == nil, "router: an option we never offered -> nothing")
func decided(_ data: Data, _ text: String) -> ArisIntent? {
    ArisRouter.parse(data).flatMap { ArisRouter.decide($0, text: text, threshold: 0.7) }
}
check(decided(jevReply("next_track", 0.92), "노래 좀 바꿔줘") == .media(.next), "router: sure about next -> next song")
check(decided(jevReply("next_track", 0.5), "노래 좀 바꿔줘") == nil, "router: unsure -> Claude")
check(decided(jevReply("ask_claude", 0.95), "음악 추천해줘") == nil, "router: a question -> Claude")
check(decided(jevReply("volume_down", 0.8), "너무 시끄러워") == .volume(.down), "router: too loud -> volume down")
check(decided(jevReply("volume_set", 0.9), "볼륨 좀 70 정도로") == .volume(.set(70)), "router: the number comes from the words")
check(decided(jevReply("volume_set", 0.9), "볼륨 적당히 맞춰줘") == nil, "router: a set with no number -> Claude")
check(decided(jevReply("open_app", 0.9, app: "KakaoTalk", 0.85), "카톡 좀") == .openApp("KakaoTalk"), "router: open the named app")
check(decided(jevReply("open_app", 0.9, app: "none", 0.9), "앱 하나 열어줘") == nil, "router: open but no app named -> Claude")
check(decided(jevReply("open_app", 0.9, app: "Safari", 0.4), "그거 열어줘") == nil, "router: unsure which app -> Claude")
check(decided(jevReply("tell_date", 0.9), "오늘이 며칠이더라") == .tellDate, "router: date answered on the Mac")
check(decided(jevReply("mute", 0.9), "조용히 해") == .volume(.mute), "router: mute")
check(decided(jevReply("brightness_set", 0.9), "화면 밝기 40") == .brightness(.set(40)), "router: brightness to a number")

