// MARK: - Aris trained wake word (voice prints)
/// A made-up "word": tones in a row, stretched in time, with a little noise, after some quiet.
func toneWord(_ hertz: [Double], seconds: Double = 0.18, stretch: Double = 1, noise: Float = 0.01, seed: Int = 1, lead: Double = 0.3) -> [Float] {
    var random = UInt64(seed)
    func jitter() -> Float { random = random &* 6364136223846793005 &+ 1442695040888963407; return Float(random >> 40) / Float(1 << 24) - 0.5 }
    var samples = [Float](repeating: 0, count: Int(lead * 16_000)).map { _ in jitter() * noise * 0.2 }
    for tone in hertz {
        let count = Int(seconds * stretch * 16_000)
        samples += (0..<count).map { Float(sin(2 * Double.pi * tone * Double($0) / 16_000)) * 0.4 + jitter() * noise }
    }
    return samples
}
let heyAris = [400.0, 900.0, 1600.0, 700.0]
check(ArisVoicePrint.features(toneWord(heyAris)).first?.count == 12, "voice print: twelve numbers per frame")
check(ArisVoicePrint.features([Float](repeating: 0, count: 100)).isEmpty, "voice print: too short -> nothing")
let trainedWake = ArisWakeModel.trained(from: [0.9, 0.95, 1.0, 1.05, 1.1].enumerated().map { toneWord(heyAris, stretch: $0.element, seed: $0.offset + 2) })
check(trainedWake?.prints.count == 5, "wake model: five recordings, five prints")
if let model = trainedWake {
    let said = ArisVoicePrint.features(toneWord(heyAris, stretch: 1.02, seed: 40))
    let saidOnAndOn = ArisVoicePrint.features(toneWord(heyAris + [1200, 300, 2000], stretch: 0.97, seed: 41))
    let other = ArisVoicePrint.features(toneWord([1800, 300, 1100, 2400], seed: 42))
    check(model.score(said) <= model.threshold, "wake model: the word again -> wake")
    check(model.score(saidOnAndOn) <= model.threshold, "wake model: the word with more after it -> wake")
    check(model.score(other) > model.threshold, "wake model: a different word -> no")
    let saved = try? JSONDecoder().decode(ArisWakeModel.self, from: JSONEncoder().encode(model))
    check(saved == model, "wake model: saves and loads")
}
check(ArisWakeModel.trained(from: [toneWord(heyAris), [Float](repeating: 0, count: 2000)]) == nil, "wake model: too few usable recordings -> nothing")
check(ArisWakeWord.heard("헤이 아리스") && ArisWakeWord.heard("Hey 아리스, 날씨") && ArisWakeWord.heard("hey, aris"), "wake: how the recognizers write Hey Aris")

// MARK: - Aris voice gate (when someone starts and stops talking)
func gateEvents(_ levels: [Float]) -> [ArisVoiceGate.Event] {
    var gate = ArisVoiceGate()
    return levels.compactMap { gate.feed($0) }
}
let hush: [Float] = Array(repeating: 0.002, count: 60), speech: [Float] = Array(repeating: 0.2, count: 50)
check(gateEvents(hush + speech + hush) == [.started(atFrame: 60), .ended(fromFrame: 60, toFrame: 110)],
      "gate: talking after quiet starts, a pause ends it")
check(gateEvents(hush + Array(repeating: 0.2, count: 3) + hush).isEmpty, "gate: a click isn't talking")
check(gateEvents(hush + speech + Array(repeating: 0.002, count: 10) + speech + hush)
      == [.started(atFrame: 60), .ended(fromFrame: 60, toFrame: 170)], "gate: a short breath doesn't end it")
check(gateEvents([Float](repeating: 0.2, count: 50)).isEmpty, "gate: already talking when it starts -> wait for a fresh start")
let hum: [Float] = Array(repeating: 0.03, count: 300), shout: [Float] = Array(repeating: 0.3, count: 50)
check(gateEvents(hum + shout + hum).first == .started(atFrame: 300), "gate: a steady hum becomes the floor")

