func approval(_ command: String) -> String? {
    let request: [String: Any] = ["id": 77, "method": "item/commandExecution/requestApproval", "params": ["threadId": "T1", "command": command]]
    let line = String(decoding: try! JSONSerialization.data(withJSONObject: request), as: UTF8.self)
    return (sentLines(codex.read(line)).first?["result"] as? [String: Any])?["decision"] as? String
}
