/// A read on a careful turn (this thread took in outside text): waiting for the read judge, never a card (the owner, 2026-11-06).
func judgedRead(_ events: [ArisBrainEvent], _ driver: ArisCodexDriver) -> Bool {
    guard case .confirm(let ask)? = events.first else { return false }
    return driver.escalation(for: ask.id)?.read != nil
}
func judgedTool(_ events: [ArisBrainEvent], _ driver: ArisCodexDriver) -> String? {
    guard case .confirm(let ask)? = events.first else { return nil }
    return driver.escalation(for: ask.id)?.read?.tool
}
