// A yes holds for the same local action (it asked twice for one Excel layout); messages are asked every time.
let remembering = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
func askedAbout(_ driver: ArisCodexDriver, _ id: Int, _ command: String) -> ArisConfirmation? {
    let line = String(decoding: try! JSONSerialization.data(withJSONObject: ["id": id, "method": "item/commandExecution/requestApproval",
                                                                             "params": ["command": command]]), as: UTF8.self)
    if case .confirm(let ask)? = driver.read(line).first { return ask }
    return nil
}
if let first = askedAbout(remembering, 1, "/bin/zsh -lc 'mv ~/a.txt ~/b.txt'") {
    _ = remembering.decide(first.id, allow: true)
    check(askedAbout(remembering, 2, "/bin/zsh -lc 'mv ~/a.txt ~/b.txt'") == nil, "codex: the same action again after a yes -> no second question")
} else { check(false, "codex: mv should be asked about the first time") }
check(askedAbout(remembering, 3, "/bin/zsh -lc 'mv ~/c.txt ~/d.txt'") != nil, "codex: a different action is still asked about")
if let message = askedAbout(remembering, 4, "/bin/zsh -lc '\(policyTools) message 엄마 hi'") {
    _ = remembering.decide(message.id, allow: true)
    check(askedAbout(remembering, 5, "/bin/zsh -lc '\(policyTools) message 엄마 hi'") != nil, "codex: sending again is asked again (never sent twice silently)")
} else { check(false, "codex: a message should be asked about") }
if let no = askedAbout(remembering, 6, "/bin/zsh -lc 'mv ~/e.txt ~/f.txt'") {
    _ = remembering.decide(no.id, allow: false)
    check(askedAbout(remembering, 7, "/bin/zsh -lc 'mv ~/e.txt ~/f.txt'") == nil, "codex: the same action again after a no in that turn -> declined, not asked")
    _ = remembering.ask("next turn")
    check(askedAbout(remembering, 8, "/bin/zsh -lc 'mv ~/e.txt ~/f.txt'") != nil, "codex: a no isn't remembered as a yes")
}
// The owner's ruling: after outside text a remembered yes is never used, and nothing new is remembered.
let taintRemember = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
if let first = askedAbout(taintRemember, 1, "/bin/zsh -lc 'mv ~/g.txt ~/h.txt'") {
    _ = taintRemember.decide(first.id, allow: true)
    check(askedAbout(taintRemember, 2, "/bin/zsh -lc 'mv ~/g.txt ~/h.txt'") == nil, "remembered yes: the identical action is still remembered when untainted")
    taintRemember.markUntrusted()
    check(askedAbout(taintRemember, 3, "/bin/zsh -lc 'mv ~/g.txt ~/h.txt'") != nil, "remembered yes: never used after outside text")
} else { check(false, "remembered yes: mv should be asked about the first time") }
if let tainted = askedAbout(taintRemember, 4, "/bin/zsh -lc 'mv ~/i.txt ~/j.txt'") {
    _ = taintRemember.decide(tainted.id, allow: true)
    _ = taintRemember.newConversation()
    check(askedAbout(taintRemember, 5, "/bin/zsh -lc 'mv ~/i.txt ~/j.txt'") != nil, "remembered yes: a yes after outside text isn't remembered, even in a clean thread")
} else { check(false, "remembered yes: a tainted mv should be asked about") }
// The key binds the exact content: a file edit's path and diff, a command's whole text, an MCP call's whole arguments.
func editStarted(_ item: String, _ diff: String) -> String {
    #"{"method":"item/started","params":{"item":{"type":"fileChange","id":"\#(item)","changes":[{"path":"/Users/me/Documents/essay.md","diff":"\#(diff)","kind":{"type":"update"}}]}}}"#
}
func editAsked(_ driver: ArisCodexDriver, _ id: Int, _ item: String) -> ArisConfirmation? {
    if case .confirm(let ask)? = driver.read(#"{"id":\#(id),"method":"item/fileChange/requestApproval","params":{"itemId":"\#(item)"}}"#).first { return ask }
    return nil
}
let editRemember = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
_ = editRemember.read(editStarted("e1", "+hello"))
if let first = editAsked(editRemember, 1, "e1") {
    _ = editRemember.decide(first.id, allow: true)
    _ = editRemember.read(editStarted("e2", "+something else"))
    check(editAsked(editRemember, 2, "e2") != nil, "remembered yes: the same file with different content asks again")
    _ = editRemember.read(editStarted("e3", "+hello"))
    check(editAsked(editRemember, 3, "e3") == nil, "remembered yes: the same file with the same content is remembered")
} else { check(false, "remembered yes: an edit to Documents should be asked about") }
let editChanges: [[String: Any]] = [["path": "/a", "diff": "+x", "kind": ["type": "update"]]]
let editKey = ArisCodexDriver.rememberKey(.fileChange(["/a"]), changes: editChanges)
check(editKey != nil && editKey == ArisCodexDriver.rememberKey(.fileChange(["/a"]), changes: editChanges)
      && editKey != ArisCodexDriver.rememberKey(.fileChange(["/a"]), changes: [["path": "/a", "diff": "+y", "kind": ["type": "update"]]])
      && editKey?.contains("/a") == true && ArisCodexDriver.rememberKey(.fileChange(["/a"]), changes: nil) == nil,
      "remember key: a file edit binds its path and a digest of its diff (unknown changes are never remembered)")
check(ArisCodexDriver.rememberKey(.shell("mv ~/a ~/b"), cwd: "/Users/me") == "shell (/Users/me): mv ~/a ~/b"
      && ArisCodexDriver.rememberKey(.shell("mv ~/a ~/b"), cwd: "/Users/me") != ArisCodexDriver.rememberKey(.shell("mv ~/a ~/c"), cwd: "/Users/me")
      && ArisCodexDriver.rememberKey(.shell("mv a b"), cwd: "/x") != ArisCodexDriver.rememberKey(.shell("mv a b"), cwd: "/y"),
      "remember key: a command binds its whole text")
check(ArisCodexDriver.rememberKey(.mcp(server: "s", tool: "t")) == nil && ArisCodexDriver.rememberKey(.browserTask("x")) == nil
      && ArisCodexDriver.rememberKey(.computerUse(app: "Notes")) == nil, "remember key: only a command or a file edit is ever remembered")
