if case .confirm? = threadAsk(3, "T1").first {
    check(otherThread?["decision"] as? String == "decline" && noThread?["decision"] as? String == "decline",
          "codex: a request for another thread, or naming none, is declined; this thread's is asked")
} else { check(false, "codex: a request for this thread should be asked about") }

check(ArisAgentPrompt.system(tools: "/t", gated: true).contains("never run `/t` alone to list them"), "prompt: the gated AI has the whole list and never explores aris-tools")
check(ArisAgentPrompt.system(tools: "/t", gated: true).contains("`/t timer pomodoro`"), "prompt: timers go to the notch's timer, not reminders")

// MARK: - aris-agent: GPT out of quota -> another AI answers
let limitedCodex = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
for kind in ["usageLimitExceeded", "rateLimitExceeded", "serverOverloaded"] {
    check(limitedCodex.read(#"{"method":"turn/completed","params":{"turn":{"status":"failed","error":{"message":"You've hit your usage limit.","codexErrorInfo":"\#(kind)"}}}}"#)
          == [.unavailable("You've hit your usage limit.")], "codex: \(kind) -> unavailable (another AI can answer)")
}
check(limitedCodex.read(#"{"method":"turn/completed","params":{"turn":{"status":"failed","error":{"message":"bad","codexErrorInfo":"badRequest"}}}}"#)
      == [.failure("GPT (Codex): bad")], "codex: other failures stay failures, named for the notch")
check(ArisBrain.codex.fallback == .antigravity && ArisBrain.antigravity.fallback == .codex && ArisBrain.claude.fallback == .codex,
      "brain: GPT falls back to Gemini, Gemini to GPT, Claude to GPT")
var health = ArisBrainHealth()
let healthStart = Date(timeIntervalSince1970: 1_000_000)
check(health.isAvailable(.codex, at: healthStart), "health: a brain is available until it runs out")
health.markUnavailable(.codex, at: healthStart)
check(!health.isAvailable(.codex, at: healthStart.addingTimeInterval(60)) && health.isAvailable(.antigravity, at: healthStart.addingTimeInterval(60)),
      "health: a brain out of quota is skipped for a while; the others aren't")
check(health.isAvailable(.codex, at: healthStart.addingTimeInterval(ArisBrainHealth.cooldown + 1)), "health: after the cooldown it's tried again")
check(health.brain(for: .codex, at: healthStart.addingTimeInterval(60)) == .antigravity, "health: a request for GPT goes to Gemini while GPT is out")
health.markUnavailable(.antigravity, at: healthStart)
check(health.brain(for: .codex, at: healthStart.addingTimeInterval(60)) == .codex, "health: both out -> ask the one requested (its error is shown)")

let limitMessage = "You’ve hit your usage limit. Upgrade to Pro (https://chatgpt.com/explore/pro), visit https://chatgpt.com/settings/usage to purchase more credits or try again at Oct 27th, 2026 12:21 AM."
let limitNow = ISO8601DateFormatter().date(from: "2026-10-26T05:50:00Z")!
let limitReset = ArisBrainHealth.resetDate(in: limitMessage, now: limitNow, timeZone: TimeZone(identifier: "America/New_York")!)
check(limitReset == ISO8601DateFormatter().date(from: "2026-10-27T04:21:00Z"), "health: Codex's 'try again at' time is read (local time)")
check(ArisBrainHealth.resetDate(in: "try again at Nov 1st, 2026 9:05 PM", now: limitNow, timeZone: TimeZone(identifier: "UTC")!)
      == ISO8601DateFormatter().date(from: "2026-11-01T21:05:00Z"), "health: 1st / PM")
check(ArisBrainHealth.resetDate(in: "rate limited", now: limitNow) == nil, "health: no time given -> nil (the usual cooldown)")
check(ArisBrainHealth.resetDate(in: "try again at Oct 1st, 2026 1:00 AM", now: limitNow) == nil, "health: a time in the past -> nil")
var waitHealth = ArisBrainHealth()
waitHealth.markUnavailable(.codex, at: limitNow, until: limitReset)
check(!waitHealth.isAvailable(.codex, at: limitNow.addingTimeInterval(3600)) && waitHealth.isAvailable(.codex, at: limitReset!),
      "health: skipped until the time Codex gave, not just the cooldown")

// MARK: - Aris: Smart Turn (does the voice sound finished?) sets how long a pause ends the turn
func turnEnds(voice ms: Int, score: Float?, words: Int = 300, text: String = "엑셀 네 개 열고 사등분 해줘") -> Bool {
    ArisTalkKey.heardEnough(sinceStart: .seconds(4), sinceLastWords: .milliseconds(words), sinceLastVoice: .milliseconds(ms),
                            complete: ArisEndpoint.looksComplete(text), turnScore: score, hanging: ArisEndpoint.isHanging(text))
}
check(turnEnds(voice: 500, score: 0.9), "smart turn: sounds finished -> half a second is enough")
check(!turnEnds(voice: 400, score: 0.9), "smart turn: sounds finished but only 0.4 s -> wait")
check(!turnEnds(voice: 900, score: 0.9, text: "엑셀 네 개 정리") && turnEnds(voice: 1400, score: 0.9, text: "엑셀 네 개 정리"),
      "smart turn: voice sounds finished but the words don't (yet) -> the normal 1.4 s (real speech: 30% of mid-sentence pauses sound finished)")
check(!turnEnds(voice: 1300, score: 0.5) && turnEnds(voice: 1400, score: 0.5), "smart turn: unsure -> the normal 1.4 s")
check(!turnEnds(voice: 2500, score: 0.1, words: 2500, text: "엑셀 네 개 정리") && turnEnds(voice: 3000, score: 0.1, words: 3000, text: "엑셀 네 개 정리"),
      "smart turn: sounds mid-thought -> up to 3 s (real finished sentences never scored this low)")
check(!turnEnds(voice: 1900, score: 0.1, words: 1900) && turnEnds(voice: 2000, score: 0.1, words: 2000),
      "smart turn: sounds mid-thought but the words look finished -> 2 s")
check(!turnEnds(voice: 1500, score: 0.9, text: "엑셀 네 개 열고"), "smart turn: the words so far hang (…열고) -> not finished, whatever the voice says")
check(turnEnds(voice: 900, score: nil), "smart turn: no score yet -> the old rules (finished sentence, 0.9 s)")
check(ArisEndpoint.isHanging("엑셀 네 개 열고") && ArisEndpoint.isHanging("내일 날씨랑") && ArisEndpoint.isHanging("이 파일을")
      && ArisEndpoint.isHanging("음악 틀고 그리고") && ArisEndpoint.isHanging("서울에서"),
      "endpoint: 고/랑/을/그리고/에서 leave the sentence hanging")
check(!ArisEndpoint.isHanging("내일 날씨 알려줘") && !ArisEndpoint.isHanging("음악 꺼") && !ArisEndpoint.isHanging(""), "endpoint: requests don't hang")
check(ArisTalkKey.turnWindow([Float](repeating: 0.1, count: 1000)).count == 128_000
      && ArisTalkKey.turnWindow([Float](repeating: 0.1, count: 1000)).prefix(127_000).allSatisfy { $0 == 0 },
      "smart turn: a short turn is padded with silence in front (as the model was trained)")
check(ArisTalkKey.turnWindow([Float](repeating: 0.1, count: 200_000)).count == 128_000, "smart turn: a long turn keeps its last 8 s")

// MARK: - Security 2026-10-26: keys/type can't reach a terminal through a loose app name
for app in ["term", "TERMINAL", "warp", "Warp Stable", "iterm", "ghost", "keychain", "1password"] {
    check(shellRisk("\(riskTools) type 'rm -rf ~/Documents' --app '\(app)'") == .confirm, "risk: typing into an app named like a terminal or vault (\(app)) -> ask first")
}
check(shellRisk("\(riskTools) keys return --app Te") == .confirm, "risk: a very short app name -> ask first")
check(shellRisk("\(riskTools) type hello --app Notes") == .auto && shellRisk("\(riskTools) type hi --app TextEdit") == .auto
      && shellRisk("\(riskTools) keys cmd+n --app Pages") == .auto, "risk: typing into an app that can't run code still runs at once")
check(ArisActions.namesMatch("microsoft word", localizedName: "Microsoft Word", fileName: "Microsoft Word")
      && ArisActions.namesMatch("TextEdit", localizedName: "텍스트 편집기", fileName: "TextEdit"),
      "tools: an app is matched by its exact name or bundle file name, any case")
check(!ArisActions.namesMatch("term", localizedName: "Terminal", fileName: "Terminal") && !ArisActions.namesMatch("", localizedName: "Notes", fileName: "Notes"),
      "tools: part of a name doesn't count as that app (keys/type)")
check(!ArisActions.isTypingSafe(bundleID: "com.apple.Terminal") && !ArisActions.isTypingSafe(bundleID: "dev.warp.Warp-Stable")
      && !ArisActions.isTypingSafe(bundleID: "com.mitchellh.ghostty") && !ArisActions.isTypingSafe(bundleID: "com.1password.1password")
      && !ArisActions.isTypingSafe(bundleID: nil), "tools: never types into terminals, password apps, or an unknown app")
check(ArisActions.isTypingSafe(bundleID: "com.apple.Notes") && ArisActions.isTypingSafe(bundleID: "com.microsoft.Word"), "tools: ordinary apps can be typed into")

// MARK: - Aris: a moment of "still listening" after an unsure end (ChatGPT's listening_intently)
check(ArisTalkKey.grace(confident: true) == .zero, "grace: voice and words both finished -> no wait")
check(ArisTalkKey.grace(confident: false) == .milliseconds(600), "grace: otherwise 0.6 s more listening (Whisper runs meanwhile)")
check(!ArisTalkKey.resumedTalking(voiceFrames: 2), "grace: a click or a breath isn't talking again")
check(ArisTalkKey.resumedTalking(voiceFrames: 4), "grace: ~0.2 s of voice is talking again -> the turn goes on")
check(ArisTalkKey.isConfidentEnd(turnScore: 0.9, complete: true, hanging: false)
      && !ArisTalkKey.isConfidentEnd(turnScore: 0.9, complete: false, hanging: false)
      && !ArisTalkKey.isConfidentEnd(turnScore: nil, complete: true, hanging: false)
      && !ArisTalkKey.isConfidentEnd(turnScore: 0.5, complete: true, hanging: false),
      "grace: only a finished voice with finished words is a confident end")

