check(ArisMicChoice.pick(defaultInput: 70, devices: [bose, builtIn, speakers]) == 90,
      "mic: Bluetooth headset is the input -> the Mac's built-in mic instead (the headset stays in music mode)")
check(ArisMicChoice.pick(defaultInput: 70, devices: [bose, speakers]) == nil, "mic: no built-in mic (lid closed) -> keep the default")
check(ArisMicChoice.pick(defaultInput: 90, devices: [bose, builtIn]) == nil && ArisMicChoice.pick(defaultInput: 50, devices: [usbMic, builtIn]) == nil,
      "mic: built-in or a USB mic is the input -> leave it")
check(ArisMicChoice.pick(defaultInput: nil, devices: [builtIn]) == nil, "mic: unknown default -> leave it")

// MARK: - Aris ducking: your voice turns Aris down at once (ChatGPT: -10 dB, hold, restore over 1 s)
check(abs(ArisDucking.duckedVolume - 0.316) < 0.01, "duck: -10 dB")
check(!ArisDucking.mayRestore(sinceDuck: .milliseconds(500)) && ArisDucking.mayRestore(sinceDuck: .milliseconds(750)),
      "duck: stays down at least 0.75 s")
check(ArisDucking.volume(restoringFor: .zero) == ArisDucking.duckedVolume && ArisDucking.volume(restoringFor: .seconds(1)) == 1
      && ArisDucking.volume(restoringFor: .milliseconds(500)) > ArisDucking.duckedVolume && ArisDucking.volume(restoringFor: .milliseconds(500)) < 1,
      "duck: back to full over one second")
check(ArisDucking.isHeadphones(transport: .bluetooth, dataSource: nil), "duck: Bluetooth output counts as headphones")
check(ArisDucking.isHeadphones(transport: .builtIn, dataSource: "hdpn") && !ArisDucking.isHeadphones(transport: .builtIn, dataSource: "ispk"),
      "duck: the Mac's headphone jack yes, its speakers no")
check(!ArisDucking.isHeadphones(transport: .other, dataSource: nil), "duck: monitor or USB speakers -> no ducking (Aris would hear itself)")

