      && abs((agyUsage?.lanes[1].fiveHour?.percent ?? 0) - 90) < 1e-9 && agyUsage?.lanes[1].weekly == nil, "usage: Antigravity's groups become lanes, remaining becomes used")
check(agyUsage?.peak(at: usageNow).rounded() == 90, "usage: the peak is the fullest window")
check(ArisUsageWindow(percent: 80, resetsAt: usageNow.addingTimeInterval(-1)).percent(at: usageNow) == 0, "usage: a window past its reset reads 0")
check(ArisUsageParse.untilReset(usageNow.addingTimeInterval(4 * 3600 + 12 * 60), now: usageNow) == "4시간 12분"
      && ArisUsageParse.untilReset(usageNow.addingTimeInterval(2 * 86400 + 3 * 3600), now: usageNow) == "2일 3시간"
      && ArisUsageParse.untilReset(usageNow.addingTimeInterval(300), now: usageNow) == "5분", "usage: time to reset reads in Korean")
let usageReport = ArisUsageReport(providers: [codexUsage!, agyUsage!])
check(ArisUsageReport.decode(usageReport.encoded()) == usageReport, "usage: the report survives JSON")

// Claude's OAuth usage, in the real shape (microsecond resets_at, null Opus and Sonnet).
