    #"{"timestamp":"2026-10-31T10:00:01.000Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":1000,"cached_input_tokens":400,"output_tokens":100,"total_tokens":1100},"last_token_usage":{"input_tokens":1000,"cached_input_tokens":400,"output_tokens":100,"total_tokens":1100}}}}"#,
    #"{"timestamp":"2026-10-31T10:00:02.000Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":1000,"cached_input_tokens":400,"output_tokens":100,"total_tokens":1100}}}}"#,
    #"{"timestamp":"2026-10-31T10:00:03.000Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":1800,"cached_input_tokens":900,"output_tokens":150,"total_tokens":1950}}}}"#,
    #"{"timestamp":"2026-10-31T10:00:04.000Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":50,"cached_input_tokens":0,"output_tokens":5,"total_tokens":55},"last_token_usage":{"input_tokens":50,"cached_input_tokens":0,"output_tokens":5,"total_tokens":55}}}}"#,
]
let codexFound = codexLines.compactMap { ArisUsageLog.codex(line: Data($0.utf8), state: &codexState) }
check(codexFound.count == 3 && codexFound.map(\.raw.usage.input) == [1000, 800, 50] && codexFound.map(\.raw.usage.cached) == [400, 500, 0]
      && codexFound.allSatisfy { $0.raw.model == "gpt-6-astra" } && codexFound[0].key == "2026-10-31T10:00:01.000Z:1100", "cost: Codex totals become deltas, zero ones skipped, a drop falls back to last_token_usage")
