      && gptX?.cacheWrite == 1 && parsedCatalog?["other"] == nil, "cost: models.dev tiers apply past their context size, only the three providers are kept")
check(ArisUsageScanner.logicalPath("/a/rollout-1.jsonl.zst") == "/a/rollout-1.jsonl" && ArisUsageScanner.logicalPath("/a/rollout-1.jsonl") == "/a/rollout-1.jsonl"
      && ArisUsageScanner.isRollout("/a/x.jsonl.zst", compressed: true) && !ArisUsageScanner.isRollout("/a/x.jsonl.zst", compressed: false)
      && ArisUsageScanner.isRollout("/a/x.jsonl", compressed: false) && !ArisUsageScanner.isRollout("/a/x.json", compressed: true), "cost: Codex's compressed rollouts are read, under their plain name")
// Line streaming: the cost scan reads logs a chunk at a time, never a whole file.
do {
    let text = Data("alpha\n\nbravo-charlie\ndelta".utf8)
    var position = 0, asked: [Int] = []
    let feed = { (buffer: UnsafeMutableRawPointer, count: Int) -> Int in
        asked.append(count)
        let n = min(count, text.count - position)
        text.copyBytes(to: buffer.assumingMemoryBound(to: UInt8.self), from: position..<position + n)
        position += n
        return n
    }
    var lines: [String] = []
    let consumed = ArisLineStream.forEachLine(chunk: 4, read: feed) { lines.append(String(decoding: $0, as: UTF8.self)) }
    check(lines == ["alpha", "", "bravo-charlie"] && consumed == 21 && !asked.isEmpty && asked.allSatisfy { $0 == 4 },
          "lines: lines longer than a chunk are joined, reads never ask for more than a chunk, an unfinished last line waits")
    position = 0
    var flushed: [String] = []
    let all = ArisLineStream.forEachLine(chunk: 3, flushTail: true, read: feed) { flushed.append(String(decoding: $0, as: UTF8.self)) }
    check(flushed == ["alpha", "", "bravo-charlie", "delta"] && all == text.count, "lines: with flushTail the unfinished last line counts too")
    let file = FileManager.default.temporaryDirectory.appendingPathComponent("aris-lines-\(UUID().uuidString).jsonl")
    try? text.write(to: file)
    var fromOffset: [String] = []
    let read = ArisLineStream.forEachLine(inFile: file, from: 6) { fromOffset.append(String(decoding: $0, as: UTF8.self)) }
    try? FileManager.default.removeItem(at: file)
    check(fromOffset == ["", "bravo-charlie"] && read == 15 && ArisLineStream.forEachLine(inFile: file, from: 0) { _ in } == nil,
          "lines: a file is read from its offset, a missing one is nil")
    var printed: [String] = []
    let ran = ArisLineStream.forEachLine(ofCommand: "/usr/bin/printf", ["x\\ny"], timeout: 5) { printed.append(String(decoding: $0, as: UTF8.self)) }
    check(ran && printed == ["x", "y"] && !ArisLineStream.forEachLine(ofCommand: "/usr/bin/false", [], timeout: 5) { _ in },
          "lines: a command's output is streamed, a failing command is false")
    let line = Data(#"{"type":"assistant","usage":{}}"#.utf8)
    check(line.withUnsafeBytes { ArisLineStream.contains($0, "\"usage\"") && !ArisLineStream.contains($0, "\"rate_limits\"") }, "lines: a needle is found in a line")
}
do {
    typealias G = ArisSlidingTabsGeometry
    let first = G.frames(weights: [1, 0, 0], width: 200, unselected: 34, spacing: 2)
    let last = G.frames(weights: [0, 0, 1], width: 200, unselected: 34, spacing: 2)
    check(first.tabWidths == [128, 34, 34] && first.indicatorX == 0 && first.indicatorWidth == 128
          && last.tabWidths == [34, 34, 128] && last.indicatorX == 72 && last.indicatorWidth == 128, "tabs: at rest the pill covers the selected tab")
    let jump = G.frames(weights: [0.5, 0, 0.5], width: 200, unselected: 34, spacing: 2)
    check(jump.tabWidths == [81, 34, 81] && jump.indicatorX == 36, "tabs: a jump over a tab leaves it alone")
    let half = G.frames(weights: [0.5, 0.5, 0], width: 200, unselected: 34, spacing: 2)
    let span = half.tabWidths[0] + 2 + half.tabWidths[1]
    check(half.indicatorWidth == 128 && abs(half.indicatorX - (span - 128) / 2) < 1e-9, "tabs: halfway the pill is centred over the two tabs")
    let cut = G.frames(weights: [0.3, 0.5, 0.2], width: 200, unselected: 34, spacing: 2)
    check(abs(cut.tabWidths.reduce(0, +) + 4 - 200) < 1e-9 && cut.indicatorX > 0 && cut.indicatorX < 72 && abs(cut.indicatorX - (0.5 * 36 + 0.2 * 72)) <= 0.25,
          "tabs: a move interrupted halfway still fills the row, the pill between the tabs")
    check(G.frames(weights: [1], width: 100, unselected: 30, spacing: 2).indicatorWidth == 100, "tabs: one tab fills the row")
    var aligned = true, filled = true
    for k in 0...20 {
        let blend = Double(k) / 20
        for width in [198.3, 197.0, 200.0] {
            let frames = G.frames(weights: [1 - blend, blend * 0.4, blend * 0.6], width: width, unselected: 30.2, spacing: 2)
            let grid = frames.tabWidths + [frames.indicatorX, frames.indicatorWidth]
            aligned = aligned && grid.allSatisfy { ($0 * 2).rounded() == $0 * 2 }
            filled = filled && abs(frames.tabWidths.reduce(0, +) + 4 - (width * 2).rounded(.down) / 2) < 1e-9
        }
    }
    check(aligned && filled, "tabs: every width and position is on the pixel grid and the row stays full")
    // Each icon goes one way from where a move starts to where it ends, never back (the end-of-move shake).
    var oneWay = true, failure = ""
    for labels: [CGFloat] in [[21, 42, 32], [21, 60, 32]] {
        for width in [147.0, 150.5, 200.0] {
            for from in 0..<3 {
                for to in 0..<3 where to != from {
                    var previous: [CGFloat]?
                    var direction = [CGFloat](repeating: 0, count: 3)
                    for k in 0...100 {
                        let t = Double(k) / 100
                        let weights = (0..<3).map { $0 == from ? 1 - t : $0 == to ? t : 0 }
                        let frames = G.frames(weights: weights, width: width, unselected: 34, spacing: 2)
                        var icons: [CGFloat] = []
                        for i in 0..<3 {
                            let lead = G.content(selectedness: frames.selectedness[i], width: frames.tabWidths[i], start: frames.starts[i],
                                                 exactStart: frames.exactStarts[i], selected: frames.indicatorWidth,
                                                 unselected: 34, label: labels[i], icon: 16, gap: 5, padding: 8).lead
                            icons.append(frames.starts[i] + lead)
                        }
                        if let previous {
                            for i in 0..<3 where icons[i] != previous[i] {
                                let step = icons[i] - previous[i]
                                if direction[i] != 0 && (step > 0) != (direction[i] > 0) && oneWay {
                                    oneWay = false
                                    failure = " (labels \(labels) width \(width) \(from)→\(to) tab \(i) at t=\(t))"
                                }
                                direction[i] = step
                            }
                        }
                        previous = icons
                    }
                }
            }
        }
    }
    check(oneWay, "tabs: every icon moves one way through a move" + failure)
    let rest = G.content(selectedness: 0, width: 34, selected: 128, unselected: 34, label: 42, icon: 16, gap: 5, padding: 8)
    let open = G.content(selectedness: 1, width: 128, selected: 128, unselected: 34, label: 42, icon: 16, gap: 5, padding: 8)
    let tight = G.content(selectedness: 1, width: 60, selected: 60, unselected: 34, label: 42, icon: 16, gap: 5, padding: 8)
    check(rest.lead == 9 && rest.visible == 0 && open.lead == 32.5 && open.visible == 42 && tight.lead == 8 && tight.visible == 23,
          "tabs: at rest an icon sits centred alone, or with its label (cut to fit inside the padding)")
}
// MARK: - to-dos on Reminders: voice phrases, grouping, the tools route
func todoIntent(_ phrase: String) -> String {
    switch ArisIntent.parse(phrase) {
    case .addTodo(let item): "add:\(item)"
    case .finishTodo(let item): "done:\(item)"
    case .listTodos: "list"
    default: "other"
    }
}
