do {
    let calendar = Calendar.current
    let now = calendar.date(from: DateComponents(year: 2026, month: 11, day: 4, hour: 12))!
    func day(_ offset: Int, _ hour: Int?) -> Date? {
        let start = calendar.date(byAdding: .day, value: offset, to: calendar.startOfDay(for: now))!
        guard let hour else { return start }
        return calendar.date(bySettingHour: hour, minute: 0, second: 0, of: start)
    }
    func item(_ title: String, _ due: Date?, time: Bool) -> ArisTodoItem {
        ArisTodoItem(id: title, title: title, notes: nil, due: due, hasTime: time, listID: "l", listName: "미리 알림", colorHex: "#ff9500")
    }
    let weekEnd = calendar.dateInterval(of: .weekOfYear, for: now)!.end
    let inWeek = weekEnd.addingTimeInterval(-3_600 * 12)
    let items = [item("c", day(0, 23), time: true), item("a", day(-1, nil), time: false), item("e", day(30, nil), time: false), item("f", nil, time: false),
                 item("d", day(1, 9), time: true), item("b", calendar.date(byAdding: .hour, value: -1, to: now), time: true), item("g", inWeek, time: false)]
    let groups: [(group: ArisTodoGroup, items: [ArisTodoItem])] = ArisTodoGroup.grouped(items, now: now)
    check(groups.map(\.group).first == .overdue && groups.first?.items.map(\.title) == ["a", "b"]
          && groups.first { $0.group == .later }?.items.map(\.title) == ["e"] && groups.last?.group == .undated && groups.last?.items.map(\.title) == ["f"]
          && groups.first { $0.group == .today }?.items.map(\.title).contains("c") == true,
          "todo: items group into overdue, today, tomorrow, this week, later, none")
    check(item("x", day(0, 15), time: true).dueText(now: now)?.hasPrefix("오늘") == true && item("x", day(1, nil), time: false).dueText(now: now) == "내일"
          && item("x", nil, time: false).dueText(now: now) == nil, "todo: due text reads 오늘 / 내일")
    check(ArisTodoMatch.one("우유 사기", in: [item("우유 사기", nil, time: false), item("빵 사기", nil, time: false)])?.title == "우유 사기"
          && ArisTodoMatch.one("사기", in: [item("우유 사기", nil, time: false), item("빵 사기", nil, time: false)]) == nil
          && ArisTodoMatch.one("a", in: [item("a", nil, time: false)]) == nil, "todo: words name exactly one item")
    let milks = [item("우유 사기", nil, time: false), item("우유 사기 (두유)", nil, time: false), item("빵 사기", nil, time: false)]
    check(ArisTodoMatch.one("우유 사기", in: milks)?.title == "우유 사기", "todo: an exact title wins over one that only contains it")
    check(ArisTodoMatch.matches("사기", in: milks).count == 3 && ArisTodoMatch.one("사기", in: milks) == nil, "todo: several matches are listed, none picked")
    check(ArisTodoMatch.unclear("사기", in: milks) == "several open items match \"사기\": 우유 사기; 우유 사기 (두유); 빵 사기. Ask the user which one.",
          "todo: several matches -> the AI is told to ask which one")
    check(ArisTodoMatch.unclear("김치", in: milks) == "no open item matches \"김치\"", "todo: none -> says so")
    check(item("x", nil, time: false).canPostponeToTomorrow(now: now) && item("x", day(-2, nil), time: false).canPostponeToTomorrow(now: now)
          && item("x", day(0, 23), time: true).canPostponeToTomorrow(now: now) && !item("x", day(1, 9), time: true).canPostponeToTomorrow(now: now)
          && !item("x", day(3, nil), time: false).canPostponeToTomorrow(now: now),
          "todo: 내일로 미루기 is offered only for undated, overdue or today's items (never pulls a later one in)")
}
