    check(ArisAgenda.featured([far, next, day], now: now)?.slot.id == "next" && ArisAgenda.featured([far, next, day], now: now)?.inProgress == false, "agenda: else the next one within 12 hours")
    check(ArisAgenda.featured([far, day], now: now) == nil, "agenda: nothing featured past 12 hours or for all-day events")
