    check(ArisAgenda.dayTitle(now, now: now) == "오늘" && ArisAgenda.dayTitle(now.addingTimeInterval(86_400), now: now) == "내일" && ArisAgenda.dayTitle(now.addingTimeInterval(2 * 86_400), now: now) == "11월 6일 금요일",
          "agenda: day headings")
    // The day timetable (Google/Notion style): events clipped to the day, overlapping ones side by side.
    let noonDay = calendar.startOfDay(for: now)
    let lateNight = ArisAgendaSlot(id: "late", start: noonDay.addingTimeInterval(-3_600), end: noonDay.addingTimeInterval(3_600), isAllDay: false)
    check(ArisAgenda.dayMinutes(slot("a", 0, 1), on: noonDay)?.start == 720 && ArisAgenda.dayMinutes(slot("a", 0, 1), on: noonDay)?.end == 780
          && ArisAgenda.dayMinutes(lateNight, on: noonDay)?.start == 0 && ArisAgenda.dayMinutes(lateNight, on: noonDay)?.end == 60
          && ArisAgenda.dayMinutes(slot("x", 20, 1), on: noonDay) == nil && ArisAgenda.dayMinutes(day, on: noonDay) == nil,
          "agenda: a timed event is clipped to the day it's drawn on; other days and all-day events are left out")
    let laid = ArisAgenda.columns([(id: "a", start: 720, end: 780), (id: "b", start: 750, end: 810), (id: "c", start: 840, end: 900), (id: "d", start: 735, end: 750)])
    check(laid["a"]?.column == 0 && laid["a"]?.of == 2 && laid["d"]?.column == 1 && laid["d"]?.of == 2
          && laid["b"]?.column == 1 && laid["b"]?.of == 2 && laid["c"]?.column == 0 && laid["c"]?.of == 1,
          "agenda: overlapping events share the width in columns; one that touches another's end reuses its column")
    check(ArisAgenda.dots([slot("a", 0, 1), slot("b", 2, 1), slot("c", 3, 1), slot("d", 4, 1), day], on: noonDay) == 5
          && ArisAgenda.dots([slot("x", 30, 1)], on: noonDay) == 0, "agenda: the date strip counts each day's events, all-day ones included")
    check(ArisAgenda.isGoogle(account: "user@gmail.com") && ArisAgenda.isGoogle(account: "Google") && ArisAgenda.isGoogle(account: "me@googlemail.com")
