       "com.openai.chat", "com.raycast.macos", "org.hammerspoon.Hammerspoon", "Python Launcher", "IDLE"].allSatisfy { ArisRiskPolicy.computerUseIsNever([$0]) }
      && !ArisRiskPolicy.computerUseIsNever(["com.apple.systempreferences", "System Settings"]),
