} else { check(false, "re-review 5: Messages code should be asked about") }
// 6. Risky words, folded and stripped, in more languages and as keys.
check(ArisRiskPolicy.mentionsRiskyStep("del\u{200B}ete") && ArisRiskPolicy.mentionsRiskyStep("ｓｅｎｄ") && ArisRiskPolicy.mentionsRiskyStep("se\u{202E}nd")
      && ["제거", "발송", "구입", "이체", "削除", "删除", "送信", "发送", "discard", "wipe", "empty trash", "log out", "logout", "quit", "force quit",
          "cmd+q", "super+q", "cmd+opt+esc", "cmd+opt+shift+q", "cmd+shift+q", "super+delete"].allSatisfy(ArisRiskPolicy.mentionsRiskyStep)
      && !ArisRiskPolicy.mentionsRiskyStep("장보기 목록"), "re-review 6: risky words are found however they're written")
// 7a. A completion counts as an app's own screen only from cua_repl.
let cuWrongServer = cuDriver()
_ = cuWrongServer.read(cuItem("started", "j1", server: "cua_repl"))
if let js = cuAsked(cuWrongServer.read(jsAsk(1, code: notesCode, call: "j1"))) {
