    _ = cuWrongServer.read(cuItem("started", "j2", server: "cua_repl"))
    check(cuWrongServer.escalation(for: cuAsked(cuWrongServer.read(jsAsk(2, code: notesCode, call: "j2")))?.id ?? "")?.judgeTainted == true,
          "re-review 7: a finish from another server is outside text")
} else { check(false, "re-review 7: clean code should be asked about") }
// 7c + 7d. Hidden line breaks and bidi marks in strings, and bindings that shadow globals, aren't read.
check(ArisJSProgram.read("const app = await cua.getApp(\"Notes\");\nawait app.typeText(\"a\u{2028}b\");") == nil
      && ArisJSProgram.read("const app = await cua.getApp(\"Notes\");\nawait app.typeText(\"a\u{202E}b\");") == nil
      && ArisJSProgram.read("const app = await cua.getApp(\"Notes\");\nawait app.typeText(\"a\u{2066}b\");") == nil,
