check(["JSON", "Object", "Array", "Math", "Promise", "console", "setTimeout", "_x", "$x"].allSatisfy { ArisJSProgram.read("const \($0) = await cua.getApp(\"Notes\");") == nil }
      && ArisJSProgram.read("const notes2 = await cua.getApp(\"Notes\");") != nil, "re-review 7: a binding that could shadow a global isn't read")
// 8. The runtime's own housekeeping isn't a card.
func housekeeping(_ id: Int, _ tool: String, _ params: [String: Any]) -> [ArisBrainEvent] {
    cuDriver().read(String(decoding: try! JSONSerialization.data(withJSONObject: ["id": id, "method": "mcpServer/elicitation/request", "params": [
        "serverName": "cua_repl", "mode": "form", "message": "Allow?",
        "_meta": ["codex_approval_kind": "mcp_tool_call", "tool_name": tool, "tool_params": params]]]), as: UTF8.self))
}
let resetEvents = housekeeping(1, "js_reset", [:])
check(cuAccepted(resetEvents) && resetEvents.contains { if case .audit = $0 { return true }; return false }
      && cuAccepted(housekeeping(2, "turn_ended", ["hook_event_name": "Stop", "session_id": "s", "turn_id": "t"]))
      && cuAsked(housekeeping(3, "js_reset", ["code": "x"])) != nil
      && cuAsked(housekeeping(4, "turn_ended", ["hook_event_name": "Stop", "session_id": "s", "turn_id": "t", "extra": "x"])) != nil
      && cuAsked(housekeeping(5, "turn_ended", ["hook_event_name": "Stop", "session_id": 1, "turn_id": "t"])) != nil
      && !ArisCodexDriver.pluginSwitches(inConfig: "").contains { $0.contains("js_reset") || $0.contains("turn_ended") },
      "security 1: housekeeping reaches Aris and goes ahead only with exactly its arguments, logged")
let declinedHousekeeping = cuDriver()
if let mv = askedAbout(declinedHousekeeping, 1, "/bin/zsh -lc 'mv ~/r.txt ~/s.txt'") { _ = declinedHousekeeping.decide(mv.id, allow: false) }
check(cuDeclined(declinedHousekeeping.read(String(decoding: try! JSONSerialization.data(withJSONObject: ["id": 2, "method": "mcpServer/elicitation/request",
    "params": ["serverName": "cua_repl", "mode": "form", "message": "Allow?", "_meta": ["codex_approval_kind": "mcp_tool_call", "tool_name": "js_reset",
    "tool_params": [String: Any]()]]]), as: UTF8.self))), "security 1: after a no this turn, housekeeping is declined too")
// Security 2: Calendar and Reminders invite and share: one card per call.
check(judgedCode("const c = await cua.getApp(\"Calendar\");\nawait c.click(1);", targets: [ArisJSTarget(name: "Calendar", bundle: "com.apple.iCal", offLimits: false)])
        == .askUser("not for the judge")
      && judgedCode("const r = await cua.getApp(\"Reminders\");\nawait r.click(1);", targets: [ArisJSTarget(name: "Reminders", bundle: "com.apple.reminders", offLimits: false)])
        == .askUser("not for the judge"), "security 2: Calendar and Reminders aren't for the judge")
// Security 3: keys are read however they're written, and only an allowlist may be judged.
check(ArisKeyCombo.read("Command + Shift + Z") == ArisKeyCombo(modifiers: ["cmd", "shift"], key: "z") && ArisKeyCombo.read("⌘⇧z") == ArisKeyCombo(modifiers: ["cmd", "shift"], key: "z")
      && ArisKeyCombo.read("shift-cmd-z")?.isAllowed == true && ArisKeyCombo.read("Enter")?.key == "return" && ArisKeyCombo.read("⌫")?.key == "delete"
      && ArisKeyCombo.read("ESC")?.isAllowed == true && ArisKeyCombo.read("shift+tab")?.isAllowed == true && ArisKeyCombo.read("PageDown")?.isAllowed == true
      && ArisKeyCombo.read("meta+c")?.isAllowed == true && ArisKeyCombo.read("cmd+q")?.isAllowed == false && ArisKeyCombo.read("alt+cmd+esc")?.isAllowed == false
      && ArisKeyCombo.read("ctrl+a")?.isAllowed == false && ArisKeyCombo.read("cmd+w")?.isAllowed == false && ArisKeyCombo.read("cmd+return")?.isAllowed == false
      && ArisKeyCombo.read("delete")?.isAllowed == false && ArisKeyCombo.read("cmd+a+b") == nil,
      "security 3: key aliases fold to one combo, and only the allowlist may be judged")
check(judgedCode("const app = await cua.getApp(\"Notes\");\nawait app.pressKey(\"⌘ - W\");") == .askUser("not for the judge")
      && judgedCode("const app = await cua.getApp(\"Notes\");\nawait app.pressKey(\"Return\");") == .proceed("Aris가 판단해서 진행"),
      "security 3: code pressing a key off the allowlist goes to the user")
// Security 4: nothing invisible inside a string, and folding strips every invisible character.
check(["a\u{00AD}b", "a\u{3164}b", "a\u{115F}b", "a\u{FFA0}b", "a\u{FE0F}", "a\u{E0100}", "a\u{E0041}b", "a\u{180E}b"].allSatisfy {
          ArisJSProgram.read("const app = await cua.getApp(\"Notes\");\nawait app.typeText(\"\($0)\");") == nil }
      && ArisRiskPolicy.mentionsRiskyStep("de\u{00AD}lete") && ArisRiskPolicy.mentionsRiskyStep("se\u{E0041}nd") && ArisRiskPolicy.mentionsRiskyStep("보\u{3164}내"),
      "security 4: invisible characters aren't read in strings and don't hide risky words")
// Messaging (the owner's ruling): every computer-use send in a chat app is one card the user taps; never auto, a countdown or the judge.
let messagesTarget = ArisJSTarget(name: "Messages", bundle: "com.apple.MobileSMS", offLimits: false, sending: true)
func chatStep(_ code: String) -> ArisJudgedStep { ArisJudgedStep(code: code, program: ArisJSProgram.read(code), targets: [messagesTarget]) }
let momCode = "const m = await cua.getApp(\"Messages\");\nawait m.selectText(1, \"엄마\");\nawait m.typeText(\"곧 갈게\");\nawait m.pressKey(\"Return\");"
check(ArisEscalation.isMessage(chatStep(momCode)) && ArisEscalation.computerUseVerdict(chatStep(momCode), tainted: false, judgement: .proceed) == .askUser("a message for the user")
      && ArisEscalation.isMessage(chatStep("const m = await cua.getApp(\"Messages\");\nawait m.click(1);")),
      "messaging: any code for a chat app is the user's card, even the user's own words, even on the judge's yes")
func chatCard(_ code: String, request: String = "엄마한테 곧 갈게 라고 보내줘") -> ArisConfirmation? {
    let driver = cuDriver()
    driver.setRequest(request)
    _ = driver.read(cuItem("started", "j1", server: "cua_repl"))
    return cuAsked(driver.read(jsAsk(1, code: code, call: "j1")))
}
if let card = chatCard(momCode) {
    check(!card.countdown && card.title == "Messages에서 보내기" && card.detail.contains("입력하는 글:\n\"곧 갈게\"")
          && card.detail.contains("코드가 고른 대화: \"엄마\"") && card.full == momCode,
          "messaging: the card lists what's typed (quoted), the chat the code picks, and the whole code")
} else { check(false, "messaging: chat code should be asked about") }
let blindCode = "const m = await cua.getApp(\"Messages\");\nawait m.click(2);\nawait m.typeText(\"내일 봐요\");\nawait m.typeText(\"줄\\n바꿈\\t탭\");\nawait m.pressKey(\"enter\");"
if let card = chatCard(blindCode) {
    check(!card.countdown && card.title == "Messages에서 보내기" && card.detail.contains("\"내일 봐요\"") && card.detail.contains("\"줄\\n바꿈\\t탭\"")
          && card.detail.contains("대화는 코드가 직접 골라요 (이름이 코드에 없어요)"),
          "messaging: every typed string is shown, control characters visibly escaped, with the warning when no chat is named")
} else { check(false, "messaging: blind chat code should be asked about") }
let mixedChat = "const m = await cua.getApp(\"Messages\");\nconst n = await cua.getApp(\"Notes\");\nawait n.click(1);\nawait m.typeText(\"곧 갈게\");\nawait m.pressKey(\"Return\");"
if let card = chatCard(mixedChat) {
    check(card.title == "Messages에서 보내기" && card.detail.contains("앱: Messages, Notes") && card.full == mixedChat, "messaging: chat code that touches another app names both")
} else { check(false, "messaging: mixed chat code should be asked about") }
let cuOtherText = cuDriver()
_ = cuOtherText.read(cuItem("started", "j1", server: "cua_repl"))
if let card = cuAsked(cuOtherText.read(jsAsk(1, code: momCode, call: "j1"))) {
    _ = cuOtherText.decide(card.id, allow: true)
    check(["click", "type_text", "press_key"].enumerated().allSatisfy { index, tool in
              cuAccepted(cuOtherText.read(cuCall(index + 2, tool, "com.apple.MobileSMS", display: "Messages", call: "j1"))) }
          && cuAsked(cuOtherText.read(cuCall(5, "paste", "com.apple.MobileSMS", display: "Messages", call: "j1"))) != nil
          && cuAsked(cuOtherText.read(cuCall(6, "drag", "com.apple.MobileSMS", display: "Messages", call: "j1"))) != nil
          && cuAsked(cuOtherText.read(cuCall(7, "click", "com.apple.finder", display: "Finder", call: "j1"))) != nil,
          "messaging: after the user's one yes its steps run, but a paste, a drag or another app still asks")
} else { check(false, "messaging: chat code should be asked about") }
// Notes lists: the checklist key in Notes only, and a literal backslash-n is caught.
check(judgedCode("const app = await cua.getApp(\"Notes\");\nawait app.pressKey(\"super+shift+l\");\nawait app.typeText(\"우유\");\nawait app.pressKey(\"Return\");\nawait app.typeText(\"계란\");")
        == .proceed("Aris가 판단해서 진행")
      && judgedCode("const app = await cua.getApp(\"TextEdit\");\nawait app.pressKey(\"cmd+shift+l\");",
                    targets: [ArisJSTarget(name: "TextEdit", bundle: "com.apple.TextEdit", offLimits: false)]) == .askUser("not for the judge"),
      "notes: cmd+shift+L (a checklist) may be judged in Notes only; Return between lines is fine")
