      && judgedCode("const app = await cua.getApp(\"Notes\");\nawait app.typeText(\"a\\\\rb\");") == .askUser("typed text has a literal \\n"),
      "notes: typed text with a literal backslash-n or -r goes to the user instead of typing garbage")
let cuLiteral = cuDriver()
if let card = cuAsked(cuLiteral.read(jsAsk(1, code: literalNewline))) {
    check(card.detail.hasPrefix(ArisEscalation.literalEscapeNote), "notes: the card says the text has a \\n that isn't a line break")
} else { check(false, "notes: literal backslash-n code should be asked about") }
check(ArisAgentPrompt.system(tools: "/t", gated: true, computerEngine: .codex).contains("pressKey(\"Return\")") && ArisAgentPrompt.system(tools: "/t", gated: true, computerEngine: .codex).contains("super+shift+l"),
      "prompt: type line by line with Return, never a backslash-n; lists in Notes are checklists")
check(ArisAgentPrompt.system(tools: "/t", gated: true).contains("one line at a time") && ArisAgentPrompt.system(tools: "/t", gated: true).contains("cmd+shift+l"),
      "prompt (Peekaboo): messaging apps take text one line at a time; lists in Notes are checklists")
// Notes lists (the user's live feedback): a title line, then a checklist with one item per line.
check(ArisActions.noteRequest(["장보기 목록", "--checklist", "우유", "계란"]) == .checklist(title: "장보기 목록", items: ["우유", "계란"])
      && ArisActions.noteRequest(["장보기 목록", "--checklist"]) == .invalid && ArisActions.noteRequest([" ", "--checklist", "우유"]) == .invalid
      && ArisActions.noteRequest([]) == .invalid && ArisActions.noteRequest(["장보기: 우유, 계란"]) == .plain(lines: ["장보기: 우유, 계란"]),
      "note: --checklist takes a title and one argument per item; with none, or no title, it's a usage error")
check(ArisActions.noteRequest(["장보기 목록\n- 우유"]) == .plain(lines: ["장보기 목록", "- 우유"])
      && ArisActions.noteRequest(["a\\nb"]) == .plain(lines: ["a\\nb"]),
      "note: only real line breaks split a plain note (a typed backslash-n stays as written)")
let checklistBody = ArisActions.noteBody(title: "장보기 <목록>", lines: ["우유 & 빵", "계란"])
check(checklistBody == "<div><h1>장보기 &lt;목록&gt;</h1></div><div>우유 &amp; 빵</div><div>계란</div>"
      && ArisActions.noteScript(body: checklistBody, show: true).contains("make new note with properties {body:\"<div><h1>")
      && ArisActions.noteScript(body: checklistBody, show: true).contains("show made")
      && !ArisActions.noteScript(body: checklistBody, show: false).contains("show") && !ArisActions.noteScript(body: checklistBody, show: false).contains("activate"),
      "note: a title line, then one line per item, escaped; only a checklist opens Notes (a plain note stays in the background)")
check(ArisActions.checklistKeys(items: 3) == ["cmd+down", "opt+shift+up", "opt+shift+up", "opt+shift+up", "cmd+shift+l"]
      && ArisActions.checklistKeys(items: 1) == ["cmd+down", "opt+shift+up", "cmd+shift+l"]
      && ArisActions.checklistKeys(items: 3)?.allSatisfy({ ArisKeyChord.parse($0) != nil }) == true
      && ArisActions.checklistKeys(items: 30) != nil && ArisActions.checklistKeys(items: 31) == nil && ArisActions.checklistKeys(items: 0) == nil,
      "note: the item paragraphs are selected from the end (⌥⇧↑) and made a checklist (⇧⌘L), 30 items at most")
check(ArisActions.isChecklist("<div><ul class=\"checklist\"><li>우유</li></ul></div>") && !ArisActions.isChecklist("<div>우유</div><div>계란</div>"),
      "note: a checklist is reported only when the note's body shows one")
for gated in [true, false] {
    let prompt = ArisAgentPrompt.system(tools: "/t", gated: gated)
    check(prompt.contains("`/t note --markdown '<markdown>'`") && prompt.contains("`- [ ] <item>`")
