// Chunks: long code is judged in parts; every part must say yes.
let bigLine = String(repeating: "가", count: 1_000)
let bigCode = "const app = await cua.getApp(\"Notes\");\n" + (0..<24).map { "await app.typeText(\"\(bigLine)\($0)\");" }.joined(separator: "\n")
let bigStep = ArisJudgedStep(code: bigCode, program: ArisJSProgram.read(bigCode), targets: [notesTarget])
let bigParts = ArisEscalation.judgeChunks(bigStep, request: "메모에 정리해 줘")
check(bigParts.count == 4 && bigParts.allSatisfy { $0.count <= ArisJudge.maxAction } && bigParts[0].hasPrefix("부분 1/3")
      && bigParts[2].hasPrefix("부분 3/3") && bigParts[3].hasPrefix("전체 판단")
      && bigParts.allSatisfy { $0.contains("메모에 정리해 줘") && $0.contains("Notes (com.apple.Notes)") && $0.contains("전체 코드 개요 (25개 호출") }
      && bigParts.prefix(3).joined().components(separatedBy: "(com.apple.Notes): typeText(").count - 1 == 24 && bigParts[2].contains("\(bigLine)23"),
      "chunks: parts split at calls each carry the whole outline; a last read judges the outline; nothing left out")
let outlineCode = "const app = await cua.getApp(\"Notes\");\n" + (0..<300).map { "await app.typeText(\"\(String(repeating: "x", count: 40))\($0)\");" }.joined(separator: "\n")
check(judgedCode(outlineCode) == .askUser("not for the judge"), "chunks: an outline too long for one read goes to the user")
check(ArisEscalation.combined([.proceed, .proceed, .proceed], parts: 3) == .proceed
