    let all = ArisActivityTab.sections(longItems, filter: .everyone, now: at, calendar: cal)
    check(one.first?.title == "Antigravity · 오늘" && all.first?.title == "Antigravity" && all.first?.teammate == "Antigravity Research Assistant",
          "teammate name: headings show a legacy long name capped; the filter keeps the whole name")
