// --- long answers (the owner, 2026-11-04): a short spoken part, the whole on screen, "읽어줘" reads it all
do {
    let more = "자세한 건 화면에 띄워 뒀어요."
    /// As the controller runs a turn: pieces into the stream (or the whole answer at once), the notch's text by how the
    /// voice took a <say> line (kept as written on an untrusted turn), then the rest.
    func streamed(_ answer: String, chunk: Int, whole: Bool = false, untrusted: Bool = false) -> (said: [String], displays: [String], shown: String) {
        var stream = ArisSpeechStream(), said: [String] = [], displays: [String] = [], piece = ""
        stream.honoursSay = !untrusted
        if whole { said += stream.add(answer) } else {
            for character in answer {
                piece.append(character)
                if piece.count == chunk { said += stream.add(piece); displays.append(stream.display); piece = "" }
            }
            if !piece.isEmpty { said += stream.add(piece); displays.append(stream.display) }
        }
        let handling: ArisSpeakable.SayHandling = untrusted ? .keep : stream.tookSayLine ? .honour : .unwrap
        let shown = ArisSpeakable.shown(answer, korean: true, say: handling)
        return (said + stream.finish(shown: shown, korean: true), displays, shown)
    }
    let long = "오늘 일정은 네 개예요. 아침 9시에 팀 회의가 있고, 11시에는 치과 예약이 있어요. 오후 2시에는 과제 마감이 있고 "
        + "저녁 7시에는 친구랑 저녁 약속이 있어요. 비가 온다고 하니 우산 챙기세요. 내일은 일정이 비어 있어요."
    let short = "올랜도는 지금 맑고 8도예요. 최고 11도, 최저 3도예요."
    let said3 = ["오늘 일정은 네 개예요.", "아침 9시에 팀 회의가 있고, 11시에는 치과 예약이 있어요."]
    for chunk in [1, 2, 3, 7, 500] {
        let l = streamed(long, chunk: chunk)
        check(l.said == said3 + [more], "long answer: its first sentences up to \(ArisSpeechStream.budget) characters, then the screen line (pieces of \(chunk)): \(l.said)")
        check(l.shown == long, "long answer: shown whole (pieces of \(chunk))")
        let s = streamed(short, chunk: chunk)
        check(s.said == ["올랜도는 지금 맑고 8도예요.", "최고 11도, 최저 3도예요."], "short answer: read whole, no screen line (pieces of \(chunk))")
    }
    check(streamed(long, chunk: 0, whole: true).said == said3 + [more], "long answer sent whole (no stream): the same summary and screen line")

    let tagged = "<say>오늘 일정은 네 개고, 저녁에 비가 와요.</say>\n- 9시 팀 회의\n- 11시 치과\n- 2시 과제 마감\n- 7시 저녁 약속"
    for chunk in [1, 2, 3, 4, 5, 6, 9, 500] {
        let t = streamed(tagged, chunk: chunk)
        check(t.said == ["오늘 일정은 네 개고, 저녁에 비가 와요.", more], "say line: only it is read, then the screen line (pieces of \(chunk)): \(t.said)")
        check(t.displays.allSatisfy { !$0.contains("<") && !$0.contains("say>") } && t.shown == "- 9시 팀 회의\n- 11시 치과\n- 2시 과제 마감\n- 7시 저녁 약속",
              "say line: the marker never shows, split anywhere; the notch keeps the full answer (pieces of \(chunk))")
    }
    check(streamed(tagged, chunk: 0, whole: true).said == ["오늘 일정은 네 개고, 저녁에 비가 와요.", more], "say line sent whole: the line, then the screen line")
    let onlySay = streamed("<say>맑아요. 8도예요.</say>", chunk: 3)
    check(onlySay.said == ["맑아요.", "8도예요."] && onlySay.shown == "맑아요. 8도예요.", "say line alone: read whole and shown, no screen line")
    let sayWithCode = streamed("<say>이렇게 하면 돼요.</say>\n```swift\nlet a = 1\n```", chunk: 4)
    check(sayWithCode.said == ["이렇게 하면 돼요.", more], "say line then code: the line, then the screen line")
    check(ArisSpeakable.shown("<SAY>짧게요.</SAY> 자세히는 이래요.", korean: true) == "자세히는 이래요.", "say line: the tags in any case")
    // r3 review: only a closed line at the very start counts; anywhere else, or left open, it is plain text.
    let inCode = "이렇게 써요.\n```html\n<say>안녕</say>\n```"
    let code = streamed(inCode, chunk: 3)
    check(code.shown == inCode && code.said == ["이렇게 써요."], "say line: a <say> inside a code block is code, shown as written: \(code.said)")
    let midAnswer = "오늘은 맑아요. <say>숨긴 말</say> 내일은 비가 와요."
    let mid = streamed(midAnswer, chunk: 2)
    // (fix-6, vm2 6: its words show, never its tags.)
    check(mid.shown == "오늘은 맑아요. 숨긴 말 내일은 비가 와요." && mid.said == ["오늘은 맑아요.", "숨긴 말 내일은 비가 와요."], "say line: a <say> mid-answer is plain text, shown and read as words: \(mid.said)")
    let unclosedAnswer = "<say>오늘 일정은 두 개예요. 9시 회의, 2시 과제예요."
    for chunk in [1, 4, 500] {
        let open = streamed(unclosedAnswer, chunk: chunk)
        check(open.shown == ArisSpeakable.withoutSayMarkup(unclosedAnswer) && !open.shown.contains("<") && open.said == ["오늘 일정은 두 개예요.", "9시 회의, 2시 과제예요."],
              "say line: one never closed is plain text, read as an answer without it (pieces of \(chunk)): \(open.said)")
    }
    let untrustedTurn = streamed(tagged, chunk: 3, untrusted: true)
    check(untrustedTurn.shown == ArisSpeakable.withoutSayMarkup(tagged) && !untrustedTurn.shown.contains("<say>") && untrustedTurn.said.first == "오늘 일정은 네 개고, 저녁에 비가 와요." && untrustedTurn.said.count == 5
          && !untrustedTurn.said.joined().contains("say"),
          "say line: an untrusted turn keeps it in the shown text and reads the answer as one without it (short: whole): \(untrustedTurn.said)")
    var late = ArisSpeechStream()
    _ = late.add("<say>짧은 말이에요")
    late.honoursSay = false
    let lateSaid = late.add("</say> 나머지예요.") + late.finish(shown: ArisSpeakable.shown("<say>짧은 말이에요</say> 나머지예요.", korean: true, say: .keep))
    check(!late.tookSayLine && lateSaid == ["짧은 말이에요 나머지예요."], "say line: turned off before the line was read, it is read as plain words: \(lateSaid)")
    let longSay = "<say>" + String(repeating: "아주 긴 요약 문장이에요. ", count: 20) + "</say>\n자세한 내용."
    let longSaid = streamed(longSay, chunk: 7).said
    check(longSaid.dropLast().joined().count <= ArisSpeakable.sayBudget && longSaid.last == more, "say line: read up to \(ArisSpeakable.sayBudget) characters")
    var dispatched = ArisSpeechStream()
    _ = dispatched.add(long)
    check(!dispatched.finish(shown: "").contains(more), "a dispatched turn (nothing shown) never says the screen line")
    check(ArisAgentStream.fenced("보이는 글 <say>몰래</say> < SAY>") == "보이는 글 [say]몰래[say] [SAY]", "outside text: a <say> in it is defused like </screen>")
    let lessThan = streamed("<b>굵게</b> 썼어요.", chunk: 1)
    check(lessThan.said == ["<b>굵게</b> 썼어요."].map(ArisSpeakable.speakable), "an answer opening with another tag is read as usual")

    // "읽어줘": the whole last answer, code and data still left out.
    let reading = ArisSpeakable.fullReading(long + "\n```swift\nlet a = 1\n```", korean: true)
    check(reading.count == 5 && reading.first == "오늘 일정은 네 개예요." && reading.last == "내일은 일정이 비어 있어요." && !reading.joined().contains("let a"),
          "read again: every sentence of the last answer, code left out")
    let taggedReading = ArisSpeakable.fullReading(tagged, korean: true)
    check(taggedReading.count == 4 && taggedReading[0].contains("9시 팀 회의") && taggedReading[3].contains("7시 저녁 약속"),
          "read again: a say-line answer reads its full part: \(taggedReading)")
    check(ArisSpeakable.readingLimit(["짧아요."]) == .seconds(40) && ArisSpeakable.readingLimit([String(repeating: "가", count: 1000)]) == .seconds(210),
          "read again: a long reading gets time enough (never the 40 s cut-off)")
    for phrase in ["읽어줘", "읽어 줘", "다 읽어줘", "다 읽어 줘", "전부 읽어", "전부 읽어줘", "끝까지 읽어줘", "다시 읽어 줘", "그거 다 읽어줘",
                   "전체 다 읽어줘", "마저 읽어줘", "처음부터 다 읽어 줄래", "좀 읽어줘", "다 읽어줘.", "Read it", "read it all", "read the whole thing",
                   "please read it out", "read all of it"] {
        check(ArisIntent.parse(phrase) == .readAgain, "intent: \"\(phrase)\" reads the last answer again")
    }
    check(ArisSpeakable.stillReadable(since: Date().addingTimeInterval(-599)) && !ArisSpeakable.stillReadable(since: Date().addingTimeInterval(-601)),
          "read again: the last answer is readable for 10 minutes")
    for phrase in ["이 메일 읽어줘", "책 읽어줘", "할 일 읽어줘", "read this email", "읽어주는 앱 열어줘", "read this", "read that"] {
        check(ArisIntent.parse(phrase) != .readAgain, "intent: \"\(phrase)\" isn't the last answer")
    }
    let conversation = ArisAgentPrompt.system(tools: "/t"), task = ArisAgentPrompt.system(tools: "/t", task: true)
    check(conversation.contains(ArisAgentPrompt.sayRule) && !task.contains(ArisAgentPrompt.sayRule) && ArisAgentPrompt.sealed(tools: "/t").contains(ArisAgentPrompt.sayRule)
          && ArisAgentPrompt.system(tools: "/t", notion: true, gated: true).contains(ArisAgentPrompt.sayRule),
          "prompts: every conversation brain (Claude, sealed, Codex, agy) is asked for a <say> line on a long answer; a background task isn't")
}

// --- bug hunt 11-06 #9: a stopped voice's buffer completions never count against the next speak()
do {
    var progress = ArisVoiceProgress()
    progress.start(1)
    for _ in 0..<10 { progress.schedule() }
    // stop() (generation 2) fires the 10 pending completions; they reach the main queue after the next speak started.
    progress.start(3)
    for _ in 0..<3 { progress.schedule() }
    let stale = (0..<10).map { _ in progress.played(1) }
    check(!stale.contains(true) && progress.played == 0, "voice progress: a stopped voice's completions are dropped")
    check(!progress.wroteAll(), "voice progress: the new voice isn't done before its own buffers played")
    check(!progress.played(3) && !progress.played(3) && progress.played(3), "voice progress: done once its own last buffer played")
    var short = ArisVoiceProgress()
    short.start(5)
    short.schedule()
    check(!short.played(5) && short.wroteAll(), "voice progress: done when everything was sent after the last buffer played")
}

// --- audio glitch: Aris lets go of the speakers' IO cycle when its voice is done; the wake mic backs off
do {
    check(ArisAudioQuiet.speakerIdle == .seconds(2), "audio quiet: the voice's engine stops 2 s after the voice ends")
    check(ArisAudioQuiet.mayStopSpeaker(scheduledFor: 3, current: 3, voicePending: false),
          "audio quiet: nothing newer and nothing playing -> the voice's engine stops")
    check(!ArisAudioQuiet.mayStopSpeaker(scheduledFor: 3, current: 4, voicePending: false),
          "audio quiet: a newer speak() took over -> the engine keeps running")
    check(!ArisAudioQuiet.mayStopSpeaker(scheduledFor: 3, current: 3, voicePending: true),
          "audio quiet: a voice still waiting to finish -> the engine keeps running")
    check(ArisAudioQuiet.restartArmsBargeIn(speaking: true, asking: false) && !ArisAudioQuiet.restartArmsBargeIn(speaking: true, asking: true)
          && !ArisAudioQuiet.restartArmsBargeIn(speaking: false, asking: false),
          "wake restart: while Aris talks the mic comes back for the barge-in (bug hunt 11-06 #11); else for the wake word")
    check(ArisAudioQuiet.wakeRestarts(after: 0, ranFor: nil) == 1, "wake restart: the first change is restart 1")
    check(ArisAudioQuiet.wakeRestarts(after: 1, ranFor: .seconds(2)) == 2
          && ArisAudioQuiet.wakeRestarts(after: 4, ranFor: .seconds(29)) == 5,
          "wake restart: a change soon after the last reopen counts as one more in a row")
    check(ArisAudioQuiet.wakeRestarts(after: 6, ranFor: .seconds(30)) == 1
          && ArisAudioQuiet.wakeRestarts(after: 6, ranFor: .seconds(600)) == 1,
          "wake restart: a microphone that ran 30 s or more starts the count again")
    check(ArisAudioQuiet.wakeRestartDelay(restarts: 1) == .seconds(1)
          && ArisAudioQuiet.wakeRestartDelay(restarts: 2) == .seconds(2)
          && ArisAudioQuiet.wakeRestartDelay(restarts: 3) == .seconds(4)
          && ArisAudioQuiet.wakeRestartDelay(restarts: 6) == .seconds(32),
          "wake restart: 1 s, then doubling while the changes keep coming")
    check(ArisAudioQuiet.wakeRestartDelay(restarts: 7) == .seconds(60)
          && ArisAudioQuiet.wakeRestartDelay(restarts: 500) == .seconds(60),
          "wake restart: never more than a minute apart, and no overflow on a long run")
    check(ArisAudioQuiet.wakeRestartDelay(restarts: 0) == .seconds(1) && ArisAudioQuiet.wakeRestartDelay(restarts: -3) == .seconds(1),
          "wake restart: a count below one waits the first delay")
}

// --- the user's B (mockups/pill-oneline.html): one line, one face slot, the star or the teammate who works, small faces + "+N"
do {
    let ids = (1...5).map { UUID(uuidString: String(format: "00000000-0000-0000-0000-%012d", 900 + $0))! }
    func w(_ i: Int, aris: Bool = false) -> ArisPillWorker { ArisPillWorker(id: ids[i], aris: aris) }
    let one = ArisPillLayout.faces([w(0, aris: true)])
    check(one.faces == [.star] && one.more == 0 && !one.small && one.holdsStar,
          "B faces: Aris's own job puts the star in the one face slot, nothing else")
    let ghost = ArisPillLayout.faces([w(1)])
    check(ghost.faces == [.mate(ids[1])] && ghost.more == 0 && !ghost.small && !ghost.holdsStar,
          "B faces: a teammate's job puts its face in the slot instead of the star (never both)")
    let done = ArisPillLayout.faces([])
    check(done.faces == [.star] && done.more == 0 && !done.small, "B faces: no live job (끝났어요) is the star's")
    let two = ArisPillLayout.faces([w(0, aris: true), w(1)])
    check(two.faces == [.star, .mate(ids[1])] && two.more == 0 && two.small, "B faces: two jobs, two small faces, no +N")
    let three = ArisPillLayout.faces([w(1), w(0, aris: true), w(2)])
    check(three.faces == [.mate(ids[1]), .star] && three.more == 1 && three.small, "B faces: three jobs, the two oldest small + \"+1\"")
    let four = ArisPillLayout.faces([w(0, aris: true), w(1), w(2), w(3)])
    check(four.faces.count == 2 && four.more == 2, "B faces: four jobs, two faces + \"+2\" (the mockup)")
    let arisTwice = ArisPillLayout.faces([w(0, aris: true), w(2, aris: true), w(1)])
    check(arisTwice.faces == [.star, .mate(ids[1])] && arisTwice.more == 1,
          "B faces: Aris is one star however many of its jobs run; the rest count in +N")
    let arisOnly = ArisPillLayout.faces([w(0, aris: true), w(2, aris: true)])
    check(arisOnly.faces == [.star] && arisOnly.more == 1 && arisOnly.small, "B faces: two of Aris's own jobs, a small star + \"+1\"")

    check(ArisPillLayout.faceWidth(count: 1, small: false) == 22 && ArisPillLayout.faceWidth(count: 1, small: true) == 18
          && ArisPillLayout.faceWidth(count: 2, small: true) == 18 + 18 - 5,
          "B faces: 22 alone, 18 small, overlapping by 5")
    check(ArisPillLayout.height == 30 && ArisPillLayout.padding == 10 && ArisPillLayout.gap == 10,
          "B pill: 30 tall like the dictation pill, 10 in, 10 between columns")

    // P1 stays: the label on the pill's (= the notch's) centre whatever the sides hold, and never under 168 wide.
    let short = ArisPillLayout.width(left: 22, center: 40, right: 24)
    check(short == ArisPillLayout.minWidth && ArisPillLayout.centerX(left: 22, center: 40, right: 24) == short / 2,
          "B pill: a short line keeps the 168 minimum and stays centred (both sides grow alike)")
    let long = ArisPillLayout.width(left: 31, center: 160, right: 26)
    let longExpected: CGFloat = 20 + 62 + 20 + 160
    check(long == longExpected && ArisPillLayout.centerX(left: 31, center: 160, right: 26) == long / 2,
          "B pill: it grows wider, not taller, and the label stays on the centre line")
    let doneWidth = ArisPillLayout.width(left: 22, center: 70, right: 0)
    check(ArisPillLayout.centerX(left: 22, center: 70, right: 0) == doneWidth / 2, "B pill: 끝났어요 (no clock) is centred too")
    let sides: [(CGFloat, CGFloat)] = [(22, 26), (31, 0), (18, 40)]
    var centred = true
    for c in stride(from: CGFloat(0), through: 300, by: 7) {
        for (l, r) in sides {
            let width: CGFloat = ArisPillLayout.width(left: l, center: c, right: r)
            let mid: CGFloat = ArisPillLayout.centerX(left: l, center: c, right: r)
            if abs(mid - width / 2) > 1e-9 || width < ArisPillLayout.minWidth { centred = false }
        }
    }
    check(centred, "B pill: for any label and sides the label's centre is the pill's, and the pill is at least 168")

    // The star's seat: the pill takes it only when the star is its face; a teammate in the slot means no star at all.
    check(ArisStarSeat.seat(mode: .tasks, band: true, pill: false, pillTaken: true) == nil
          && ArisStarSeat.seat(mode: .home, band: true, pill: false, pillTaken: true) == nil
          && ArisStarSeat.seat(mode: nil, band: false, pill: false, pillTaken: true) == nil,
          "B seat: a teammate's face holds the pill's slot, so the star isn't drawn (never both)")
    check(ArisStarSeat.seat(mode: .turn, band: true, pill: false, pillTaken: true) == .band,
          "B seat: during the main turn the star stays beside the camera even while a teammate's pill shows")
    check(ArisStarSeat.seat(mode: .tasks, band: true, pill: true, pillTaken: false) == .pill
          && ArisStarSeat.seat(mode: .tasks, band: true, pill: false, pillTaken: false) == .band,
          "B seat: the star's own pill takes it; no pill, the band")
    check(ArisStarHop.scale(from: 1, to: 1.1, progress: 0) == 1 && abs(ArisStarHop.scale(from: 1, to: 1.1, progress: 1) - 1.1) < 1e-9
          && abs(ArisStarHop.scale(from: 1, to: 0.9, progress: 0.5) - 0.95) < 1e-9,
          "B seat: the star grows or shrinks to its seat's size along the hop")
}

